INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_b957c466-9e12-415c-a520-465df629f1cc', 'Krämig kycklinggryta med soltorkade tomater', 4, '🍗', '["gryta", "kyckling", "vardag"]',
 '[{"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Kycklingfilé", "amount": 650, "unit": "g"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Crème fraiche", "amount": 2, "unit": "dl"}, {"name": "Kycklingbuljong", "amount": 2.5, "unit": "dl"}, {"name": "Soltorkade tomater", "amount": 1, "unit": "förp"}, {"name": "Gröna ärtor", "amount": 250, "unit": "g"}]',
 '["Tina kycklingen om fryst används.", "Koka riset enligt anvisning på förpackningen.", "Strimla kycklingen och stek den i oljan i en stekpanna och krydda med salt och peppar. Sänk värmen, pressa i vitlöken och häll i crème fraiche och buljong.", "Strimla tomaterna och rör ner i grytan och sjud ca 5 minuter.", "Koka ärtorna i saltat vatten enligt anvisningen på förpackningen eller sockerärtorna i ca 2 minuter.", "Servera grytan med ris och ärtor."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_a57f0346-cb47-47cf-a3b1-1305d4478e9a', 'Marry me chicken', 4, '🍗', '["kyckling", "vardag"]',
 '[{"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Kycklingfiléer", "amount": 4, "unit": "st"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Vetemjöl", "amount": 0.5, "unit": "dl"}, {"name": "Strimlade soltorkade tomater", "amount": 1, "unit": "förp"}, {"name": "Olivolja", "amount": 2, "unit": "msk"}, {"name": "Vitlöksklyftor", "amount": 2, "unit": "st"}, {"name": "Chiliflakes", "amount": 1, "unit": "krm"}, {"name": "Torkad oregano", "amount": 0.5, "unit": "tsk"}, {"name": "Torkad timjan", "amount": 0.5, "unit": "tsk"}, {"name": "Vatten", "amount": 2.5, "unit": "dl"}, {"name": "Kycklingbuljongtärning", "amount": 0.5, "unit": "st"}, {"name": "Vispgrädde", "amount": 2.5, "unit": "dl"}, {"name": "Riven parmesan", "amount": 1.5, "unit": "dl"}, {"name": "Kruka basilika", "amount": 1, "unit": "st"}, {"name": "Sallad", "amount": 1, "unit": "st"}, {"name": "Parmesan", "amount": 1, "unit": "st"}]',
 '["Koka riset enligt anvisningen på förpackningen.", "Krydda kycklingen med salt och peppar och vänd filéerna i mjölet.", "Häll av de soltorkade tomaterna.", "Bryn kycklingen i hälften av oljan i en stekpanna. Lyft upp kycklingen och lägg dem på en tallrik.", "Tillsätt resten av oljan i stekpannan. Pressa i vitlöken och rör i tomaterna. Låt fräsa 1 minut och tillsätt kryddorna, vatten, smulad buljongtärning, grädde och parmesan. Låt koka upp under omrörning.", "Lägg i kycklingen och sjud i ca 15 minuter eller tills kycklingen har en innertemperatur på 70˚C. Vänd kycklingen några gånger under tillagningen.", "Strimla basilikan och blanda ner i såsen.", "Till servering: Servera kycklingen med riset, lite extra riven parmesan och gärna en enkel sallad."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_39be6a77-214c-4924-82bb-aa0cf93af65a', 'Grekisk plåt', 4, '🥬', '["barn", "enkel", "vardag", "vegetariskt"]',
 '[{"name": "Fast potatis", "amount": 500, "unit": "g"}, {"name": "Kokta kikärtor", "amount": 1, "unit": "förp"}, {"name": "Urkärnade svarta oliver", "amount": 1, "unit": "dl"}, {"name": "Olja", "amount": 2, "unit": "msk"}, {"name": "Torkad oregano", "amount": 2, "unit": "tsk"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Lammkorv", "amount": 300, "unit": "g"}, {"name": "Rödlök", "amount": 1, "unit": "st"}, {"name": "Tomater", "amount": 2, "unit": "st"}, {"name": "Fetaost", "amount": 150, "unit": "g"}, {"name": "Tzatziki", "amount": 1, "unit": "st"}, {"name": "Färsk oregano", "amount": 1, "unit": "st"}]',
 '["Sätt ugnen på 225°C.", "Skär potatisen i bitar. Häll av och skölj kikärterna, torka torra med hushållspapper. Lägg potatis, kikärter och oliver på en plåt och blanda med olja, oregano och salt.", "Ställ in i mitten av ugnen ca 15 minuter. Skär lammkorven i bitar och lägg på plåten. Ställ in i ugnen ytterligare ca 10 minuter.", "Skala och skiva löken tunt. Tärna tomaterna. Toppa plåten med rödlök, tomater och smulad fetaost.", "Tillbehör: Servera med tzatziki."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_c6cdce15-9fa0-449c-921d-1673c56740d6', 'Palak paneer med tomat och halloumi', 4, '🍲', '["gryta", "vardag", "vegetariskt"]',
 '[{"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Gul lök", "amount": 1, "unit": "st"}, {"name": "Vitlöksklyftor", "amount": 2, "unit": "st"}, {"name": "Tomater", "amount": 2, "unit": "st"}, {"name": "Riven ingefära", "amount": 2, "unit": "msk"}, {"name": "Olivolja", "amount": 3, "unit": "msk"}, {"name": "Tomatpuré", "amount": 2, "unit": "msk"}, {"name": "Garam masala", "amount": 1, "unit": "msk"}, {"name": "Krossade tomater", "amount": 390, "unit": "g"}, {"name": "Vatten", "amount": 1, "unit": "dl"}, {"name": "Vispgrädde", "amount": 2, "unit": "dl"}, {"name": "Grönsaksbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Färsk spenat", "amount": 200, "unit": "g"}, {"name": "Halloumi", "amount": 400, "unit": "g"}, {"name": "Salt", "amount": 2, "unit": "krm"}]',
 '["Koka riset enligt anvisningen på förpackningen.", "Skala lök och vitlök. Skär gula löken och tomaterna i klyftor. Skiva vitlöken. Skala och riv ingefäran fint på ett rivjärn.", "Hetta upp hälften av olivoljan i en stekgryta eller kastrull. Fräs lök, vitlök, ingefära, tomatpuré och garam masala 3-4 minuter.", "Tillsätt tomater, krossade tomater, vatten, grädde och smulad buljongtärning. Låt sjuda 6-7 minuter. Vänd ner spenaten.", "Skär osten i tärningar och stek dem gyllene i resten av olivoljan i en stekpanna.", "Blanda ner osten i grytan och smaka av med salt. Servera med ris."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_b90e9e55-009e-4818-89e1-6de61bd64d42', 'Spaghetti och köttfärssås', 4, '🍗', '["kyckling", "köttfärs", "pasta", "vardag"]',
 '[{"name": "Gul lök", "amount": 1, "unit": "st"}, {"name": "Vitlöksklyftor", "amount": 2, "unit": "st"}, {"name": "Morötter", "amount": 2, "unit": "st"}, {"name": "Nötfärs", "amount": 500, "unit": "g"}, {"name": "Matolja", "amount": 2, "unit": "msk"}, {"name": "Tomatpuré", "amount": 0.5, "unit": "dl"}, {"name": "Krossade tomater", "amount": 500, "unit": "g"}, {"name": "Vatten", "amount": 2.5, "unit": "dl"}, {"name": "Kycklingbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Kinesisk soja", "amount": 1, "unit": "tsk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}, {"name": "Spaghetti", "amount": 4, "unit": "port"}, {"name": "Parmesan", "amount": 1, "unit": "st"}, {"name": "Sallad", "amount": 1, "unit": "st"}, {"name": "Färsk timjan", "amount": 1, "unit": "st"}]',
 '["Skala och hacka lök och vitlök. Skala och riv morötterna grovt på ett rivjärn.", "Bryn köttfärsen och grönsakerna i oljan i en stor stekpanna eller gryta, tillsätt tomatpuré och bryn med den ett tag.", "Tillsätt krossade tomater, vatten, smulad buljongtärning och soja. Koka sakta 15 minuter, smaka av med salt och peppar.", "Koka spaghettin enligt anvisningen på förpackningen.", "Till servering: Servera med riven parmesanost och en god sallad."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_344bc4bc-8ee9-46ec-baa4-11b647dd0975', 'Krämig tacopaj', 4, '🌮', '["vardag"]',
 '[{"name": "Smör", "amount": 50, "unit": "g"}, {"name": "Vetemjöl", "amount": 3, "unit": "dl"}, {"name": "Kvarg", "amount": 1, "unit": "dl"}, {"name": "Kallt vatten", "amount": 3, "unit": "msk"}, {"name": "Bland", "amount": 500, "unit": "g"}, {"name": "Smör", "amount": 1, "unit": "msk"}, {"name": "Santa Maria taco kryddmix", "amount": 2, "unit": "tsk"}, {"name": "Vatten", "amount": 1, "unit": "dl"}, {"name": "Crème fraiche med paprika & chili", "amount": 2, "unit": "dl"}, {"name": "Körsbärstomater", "amount": 250, "unit": "g"}, {"name": "Riven ost", "amount": 2.5, "unit": "dl"}, {"name": "Sallad", "amount": 1, "unit": "st"}]',
 '["Hacka samman matfettet skuret i mindre bitar med mjölet till en grynig massa. Tillsätt kvarg och vatten. Arbeta snabbt ihop till en deg.", "Kavla eller tryck ut degen i en pajform ca 28 cm i diameter (för 4 port). Nagga degen med en gaffel. Ställ formen i kylskåp ca 30 minuter.", "Sätt ugnen på 225°C", "Förgrädda pajskalet mitt i ugnen ca 15 minuter.", "Bryn färsen i matfettet. Tillsätt tacokrydda och vatten. Rör om och låt sjuda på svag värme tills vattnet nästan kokat in. Rör i crème fraichen och sjud några minuter till.", "Fyll pajskalet med färsfyllningen. Halvera körsbärstomaterna och fördela ovanpå pajen. Strö över osten.", "Grädda mitt i ugnen ca 20 minuter.", "Till servering: Servera pajen med sallad."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_368f9400-aa37-4a44-9fdc-4fb55aba271c', 'Pannkakor - grundsmet', 4, '🥞', '[\"barn\", \"husmanskost\", \"vardag\"]',
 '[{"name": "Vetemjöl", "amount": 2.5, "unit": "dl"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Mjölk", "amount": 6, "unit": "dl"}, {"name": "Ägg", "amount": 3, "unit": "st"}, {"name": "Smör", "amount": 1, "unit": "st"}, {"name": "Sylt, bär", "amount": 1, "unit": "st"}]',
 '["En sats på 4 portioner blir 8-10 pannkakor beroende på storleken på stekpannan.", "Blanda mjöl och salt i en bunke. Vispa i hälften av mjölken och vispa till en slät smet. Vispa i resten av mjölken och äggen. Låt smeten vila ca 10 minuter.", "Stek tunna pannkakor i lite smör, för varje pannkaka, i en stek- eller pannkakspanna.", "Servera med sylt, bär eller frukt eller med salta tillbehör som Räksalsa med gurka och lime, Rökt lax med dillkräm eller Avokadoröra med bacon och tomat."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_ef815223-5703-476e-a232-0649a88727fe', 'Lysande gul fiskgryta', 4, '🐟', '["fisk", "gryta", "lax", "soppa", "vardag"]',
 '[{"name": "Torskfilé, sej", "amount": 400, "unit": "g"}, {"name": "Laxfilé", "amount": 300, "unit": "g"}, {"name": "Purjolök", "amount": 0.5, "unit": "st"}, {"name": "Gul lök", "amount": 0.5, "unit": "st"}, {"name": "Smör", "amount": 1, "unit": "msk"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Tomatpuré", "amount": 1.5, "unit": "tsk"}, {"name": "Torkad timjan", "amount": 1, "unit": "tsk"}, {"name": "Torkad basilika", "amount": 1, "unit": "tsk"}, {"name": "Torrt vitt vin", "amount": 2.5, "unit": "dl"}, {"name": "Fiskbuljongtärning", "amount": 1.5, "unit": "st"}, {"name": "Vispgrädde", "amount": 2, "unit": "dl"}, {"name": "Crème fraiche", "amount": 1, "unit": "dl"}, {"name": "Vatten", "amount": 2, "unit": "dl"}, {"name": "Pkt saffran", "amount": 1, "unit": "st"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Räkor med skal", "amount": 300, "unit": "g"}, {"name": "Musslor", "amount": 1, "unit": "burk"}, {"name": "Bröd och vitlöksmajonnäs", "amount": 1, "unit": "st"}]',
 '["Tina fisken (om fryst används). Skölj, ansa och strimla purjon. Skala och hacka löken.", "Smält smöret i en stor gryta eller tjockbottnad kastrull. Fräs löken och purjolöken (spara lite till servering) ett par minuter tills de blivit glansiga och genomskinliga. Pressa i vitlök. Rör ner tomatpuré, timjan och basilika. Låt detta fräsa med en kort stund.", "Tillsätt vin och buljongtärning. Koka ett par minuter. Rör ner vispgrädde, crème fraiche, vatten och saffran. Sjud i 15 minuter. Smaka av med salt.", "Skär fisken i munsbitar, lägg i grytan och sjud i ytterligare 7 minuter.", "Skala räkorna. Tillsätt dem och de avrunna musslorna. Toppa soppan med purjolöksstrimlor.", "Serveringsförslag: Hetta upp och servera genast, gärna med bröd och vitlöksmajonnäs."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_aa1d2419-4581-43ea-a3ef-87409a8b4841', 'Fläskfilégryta med champinjoner', 4, '🍲', '["gryta", "vardag"]',
 '[{"name": "Fläskfilé", "amount": 500, "unit": "g"}, {"name": "Smör", "amount": 2, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Gul lök", "amount": 1, "unit": "st"}, {"name": "Champinjoner", "amount": 250, "unit": "g"}, {"name": "Tomatpuré", "amount": 2, "unit": "tsk"}, {"name": "Hönsbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Vispgrädde", "amount": 3, "unit": "dl"}, {"name": "Mjölk", "amount": 2, "unit": "dl"}, {"name": "Japansk soja", "amount": 2, "unit": "msk"}, {"name": "Dijonsenap", "amount": 2, "unit": "tsk"}, {"name": "Majsstärkelse", "amount": 1, "unit": "tsk"}, {"name": "Kokt ris", "amount": 1, "unit": "st"}, {"name": "Sallad", "amount": 1, "unit": "st"}]',
 '["Skär fläskfilén i strimlor och bryn i hälften av smöret och salta och peppra. Lägg upp på en tallrik.", "Skala och hacka löken. Ansa och dela svampen. Bryn lök och svamp i en stor gryta i resten av smöret. Tillsätt tomatpurén mot slutet och låt bryna någon minut under omrörning.", "Smula ner buljongtärningen och rör i grädde och mjölk, låt koka upp. Smaka av med soja och senap, salt och peppar. Rör ut majsstärkelsen i lite vatten och rör ner. Vänd ner köttet i grytan och låt den bli varm.", "Till servering: Servera grytan med ris eller kokt potatis och en sallad."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_484a9cf1-4086-43dc-9653-563d067ee7a9', 'Ugnsstekt kycklingklubba (grundrecept)', 4, '🍗', '["kyckling", "vardag"]',
 '[{"name": "Frysta", "amount": 1, "unit": "kg"}, {"name": "Japansk soja", "amount": 2.5, "unit": "msk"}, {"name": "Ketchup", "amount": 1, "unit": "msk"}, {"name": "Rosmarin", "amount": 1, "unit": "tsk"}, {"name": "Oregano", "amount": 1, "unit": "tsk"}, {"name": "Rapsolja", "amount": 1, "unit": "msk"}, {"name": "Nymalen svartpeppar", "amount": 0.5, "unit": "tsk"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Smör", "amount": 3, "unit": "msk"}, {"name": "Vatten", "amount": 1, "unit": "dl"}, {"name": "Rostade rotfrukter", "amount": 1, "unit": "st"}, {"name": "Het yoghurtsås", "amount": 1, "unit": "st"}]',
 '["Sätt ugnen på 225°C.", "Blanda soja, ketchup, rosmarin och oregano med olja och peppar. Skala och pressa ner vitlöken.", "Lägg kycklingklubborna i en ugnssäker form och pensla på blandningen. Klicka över smör. Häll vatten i bottnen av formen.", "Stek kycklingklubborna i ugnen i ca 45 minuter (ca 30 minuter om de är färska), tills köttsaften är klar och innertemperaturen är 82˚C (intill benet). Ös kycklingen ett par gånger under tillagningen.", "Häll i mer vatten om det skulle behövas. Spara gärna skyn. Häll ner den i en skål eller en burk och förvara i kylskåpet. Ta bort ev fett som ligger överst före användning.", "Till servering: Servera gärna en av de nylagade kycklingklubborna till rostade rotfrukter med het yoghurtsås, t ex Ugnsrostade rotfrukter och Het yoghurtsås."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_6e60fc60-a0fb-4322-8aa9-98de3f835d5d', 'Broccolipaj', 4, '🥧', '["vardag"]',
 '[{"name": "Vetemjöl", "amount": 2.5, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "krm"}, {"name": "Smör", "amount": 125, "unit": "g"}, {"name": "Kallt vatten", "amount": 1, "unit": "msk"}, {"name": "Smör", "amount": 1, "unit": "msk"}, {"name": "Broccoli", "amount": 250, "unit": "g"}, {"name": "Riven prästost", "amount": 150, "unit": "g"}, {"name": "Ägg", "amount": 4, "unit": "st"}, {"name": "Mjölk", "amount": 1, "unit": "dl"}, {"name": "Matlagningsgrädde", "amount": 2.5, "unit": "dl"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Svartpeppar", "amount": 2, "unit": "krm"}, {"name": "Solroskärnor", "amount": 1, "unit": "dl"}]',
 '["Pajdeg: Blanda vetemjöl, salt och smör i tärningar med fingertopparna i en bunke eller använd matberedare.", "Tillsätt kallt vatten och knåda snabbt ihop till en deg. Platta ut degen lite och lägg den, i plastfolie, i kylen att vila i minst 30 minuter. Degen kan med fördel göras en dag i förväg.", "Sätt ugnen på 200°C.", "Tryck ut degen i en smord pajform, 27 cm i diameter (för 4 port).", "Nagga degen i pajformen med en gaffel. Förgrädda pajskalet mitt i ugnen ca 10 minuter.", "Fyllning: Skär broccolikronan i små buketter. Skala och skär stjälken i ca 1/2 cm tjocka skivor. Koka broccolin i saltat vatten ca 3 minuter. Häll av i ett durkslag och spola den kall. Låt broccolin rinna av ordentligt.", "Riv osten. Blanda ägg, mjölk, grädde, salt, peppar och ost.", "Lägg broccoli och solroskärnor i pajskalet och häll över äggstanningen. Sätt in pajen mitt i ugnen ca 30 minuter eller tills äggstanningen stelnat."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_f81abb73-3bd0-4a9f-91b7-7c935745f165', 'Linsgryta med kokosmjölk', 4, '🍲', '["gryta", "snabb", "vardag", "vegetariskt"]',
 '[{"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Gul lök", "amount": 1, "unit": "st"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Curry", "amount": 1, "unit": "tsk"}, {"name": "Tomatpuré", "amount": 2, "unit": "msk"}, {"name": "Kokosmjölk", "amount": 400, "unit": "ml"}, {"name": "Vatten", "amount": 2.5, "unit": "dl"}, {"name": "Grönsaksbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Torkade röda linser", "amount": 2, "unit": "dl"}, {"name": "Sambal oelek", "amount": 1, "unit": "tsk"}, {"name": "Naanbröd", "amount": 2, "unit": "förp"}, {"name": "Körsbärstomater", "amount": 250, "unit": "g"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Kruka koriander", "amount": 0.5, "unit": "st"}, {"name": "Matyoghurt", "amount": 2, "unit": "dl"}]',
 '["Koka riset enligt anvisningen på förpackningen.", "Sätt på ugnen enligt anvisningen på brödförpackningen.", "Skala och hacka löken. Fräs den i oljan i en gryta. Pressa i vitlök och tillsätt curry och tomatpuré och fräs ytterligare någon minut.", "Rör i kokosmjölk, vatten, smulad buljongtärning, linser och sambal oelek. Låt koka ca 15 minuter eller tills linserna är mjuka. Späd eventuellt med mer vatten.", "Tillaga naanbröden enligt anvisningen på förpackningen.", "Dela tomaterna och vänd ner dem i grytan mot slutet av koktiden eller servera dem till. Smaka av grytan med salt och peppar.", "Servera grytan med ris och tomater, naanbröd samt yoghurt och toppa med koriander."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_fdf47512-6513-4124-9ad2-a3afe1bad9bd', 'Fläskpannkaka', 4, '🥞', '["barn", "vardag"]',
 '[{"name": "Mjölk", "amount": 8, "unit": "dl"}, {"name": "Vetemjöl", "amount": 4, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Ägg", "amount": 4, "unit": "st"}, {"name": "Fläskkött", "amount": 300, "unit": "g"}, {"name": "Lingonsylt", "amount": 1, "unit": "st"}]',
 '["Sätt ugnen på 200°C.", "Häll hälften av mjölken i en skål. Vispa ner mjöl och salt till en jämn smet. Häll i resten av mjölken. Vispa sist ner äggen.", "Skär fläsket i små tärningar. Bryn dem i en stekpanna. Fördela fläsket och stekfettet i en långpanna, 30x40 cm (för 4 port, bilden visar fläskpannkaka för 2 port) gärna med bakplåtspapper, fukta plåten lite och lägg på bakplåtspappret så ligger det still. Häll smeten över fläsktärningarna.", "Grädda i mitten av ugnen ca 30 min. Servera med lingonsylt."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_5a28698f-ad5b-4895-8fc5-2fa7d7874c2c', 'Köttfärslimpa med gräddsås', 4, '🍲', '["köttfärs", "vardag"]',
 '[{"name": "Potatis", "amount": 900, "unit": "g"}, {"name": "Ströbröd", "amount": 0.5, "unit": "dl"}, {"name": "Mjölk", "amount": 1, "unit": "dl"}, {"name": "Ägg", "amount": 1, "unit": "st"}, {"name": "Dijonsenap", "amount": 1, "unit": "msk"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Peppar", "amount": 1, "unit": "krm"}, {"name": "Blandfärs", "amount": 500, "unit": "g"}, {"name": "Rödlök", "amount": 0.5, "unit": "st"}, {"name": "Olja", "amount": 1, "unit": "tsk"}, {"name": "Matlagningsgrädde", "amount": 2.5, "unit": "dl"}, {"name": "Mjölk", "amount": 1, "unit": "dl"}, {"name": "Rosmarin", "amount": 0.5, "unit": "tsk"}, {"name": "Köttbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Majsstärkelse", "amount": 1, "unit": "tsk"}, {"name": "Ask färsk gräslök", "amount": 0.5, "unit": "st"}, {"name": "Tomater", "amount": 3, "unit": "st"}]',
 '["Sätt på ugnen på 225°C.", "Koka potatisen.", "Köttfärslimpa: Blanda ströbröd, mjölk, ägg, senap, salt och peppar. Låt svälla några minuter.", "Blanda färsen med ströbrödsblandningen. Dela färsen i två delar och forma till två smala limpor i en ugnssäker form. Sätt in den mitt i ugnen tills limpornas innertemperatur är 72°C, ca 25 minuter.", "Sås: Skala och hacka löken. Fräs den i oljan i en kastrull. Tillsätt grädde, mjölk, rosmarin och smulad buljongtärning. Blanda majsstärkelsen med lite kallt vatten och vispa ner i såsen. Koka såsen under omrörning ca 3 minuter. Smaka av såsen med salt och peppar.", "Hacka gräslöken och dela tomaterna i bitar. Strö gräslöken över tomater och köttfärslimpa.", "Servera köttfärslimpan med sås, tomater och potatis."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_1c7ba1d6-b1b3-4300-aa5e-624f2f1a1194', 'Ugnspannkaka (grundrecept)', 4, '🥞', '["barn", "husmanskost", "vardag"]',
 '[{"name": "Vetemjöl", "amount": 4, "unit": "dl"}, {"name": "Strösocker", "amount": 1, "unit": "tsk"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Mjölk", "amount": 8, "unit": "dl"}, {"name": "Ägg", "amount": 4, "unit": "st"}, {"name": "Smör", "amount": 1, "unit": "st"}]',
 '["Sätt ugnen på 225°C.", "Blanda mjölet med socker och salt i en bunke.", "Tillsätt hälften av mjölken och vispa till en jämn, tjock smet. Rör ner äggen.", "Vispa ner resterande mjölk och fortsätt vispa till en klumpfri smet (om tiden finns låt smeten svälla ca 10 minuter).", "Häll smeten i en smord långpanna, ca 30 x 40 cm (för 4 port).", "Grädda i mitten av ugnen 30-40 minuter, lägg ev. på en bit folie mot slutet om ytan får för mycket färg. Låt vila i 5 minuter innan servering. Se här hur du kan piffa din ugnspannkaka."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_cbab0ef9-7e9d-4c83-9ba9-28b686dee882', 'Krämig carbonara', 4, '🍝', '["pasta", "vardag"]',
 '[{"name": "Spaghetti", "amount": 4, "unit": "port"}, {"name": "Bacon", "amount": 2, "unit": "förp"}, {"name": "Ägg", "amount": 4, "unit": "st"}, {"name": "Vispgrädde", "amount": 1, "unit": "dl"}, {"name": "Riven parmesan", "amount": 2, "unit": "dl"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Nymalen svartpeppar", "amount": 2, "unit": "krm"}, {"name": "Rucola", "amount": 65, "unit": "g"}]',
 '["Koka spaghettin enligt anvisningen på förpackningen.", "Klipp bacon i ca 2 cm stora bitar. Stek baconbitarna knapriga i en stekpanna.", "Vispa ihop ägg (både äggvita och -gula), grädde, parmesanost, salt och svartpeppar i en bunke.", "Häll av pastan och häll tillbaka den i kastrullen, vänd ner äggblandningen och det stekta baconet. Rör runt på svag värme till en krämig pasta.", "Till servering: Servera carbonaran toppad med rucola och dra några extra tag med pepparkvarnen över."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_d0544c77-ae93-4d89-9f34-cde2dce5f25f', 'Köttfärssås med spaghetti', 4, '🍝', '["pasta", "vardag"]',
 '[{"name": "Morötter", "amount": 2, "unit": "st"}, {"name": "Nötfärs", "amount": 500, "unit": "g"}, {"name": "Olivolja", "amount": 1, "unit": "msk"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Timjan", "amount": 2, "unit": "tsk"}, {"name": "Krossade tomater", "amount": 500, "unit": "g"}, {"name": "Balsamvinäger", "amount": 1, "unit": "msk"}, {"name": "Köttbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Spaghetti", "amount": 4, "unit": "port"}, {"name": "Kruka persilja", "amount": 0.5, "unit": "st"}, {"name": "Tomater", "amount": 3, "unit": "st"}, {"name": "Olivolja", "amount": 1, "unit": "tsk"}, {"name": "Rödvinsvinäger", "amount": 1, "unit": "tsk"}]',
 '["Sätt på en stor kastrull med vatten till spaghettin.", "Skala och riv morötterna på ett rivjärn.", "Bryn färsen i olivoljan i en stor kastrull eller stekpanna med höga kanter. Pressa i vitlöken. Blanda i morötterna och låt det fräsa ca 3 minuter.", "Tillsätt timjan, krossade tomater, balsamvinäger och smulad buljongtärning.", "Sänk värmen och låt såsen sjuda ca 10 minuter under lock. Smaka av med salt och peppar.", "Koka spaghettin enligt anvisningen på förpackningen.", "Hacka persiljan. Skär tomaterna i bitar och blanda med persilja, olivolja och rödvinsvinäger. Krydda med salt och peppar.", "Servera köttfärssåsen med spaghetti och tomater."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_14839eda-c9bc-426c-ad76-fbeb63887358', 'Klassisk pajdeg- grundrecept', 1, '🥧', '["vardag"]',
 '[{"name": "Vetemjöl", "amount": 3, "unit": "dl"}, {"name": "Kylskåpskallt smör", "amount": 125, "unit": "g"}, {"name": "Iskallt vatten", "amount": 1, "unit": "msk"}]',
 '["Skär smöret i små bitar.", "Nyp ihop mjöl och smör för hand eller mixa i matberedare till en smulig massa.", "Tillsätt vattnet och blanda snabbt ihop till en deg. Tryck ut degen i en pajform (ca 25-28 cm i diameter). Nagga bottnen med en gaffel. Låt vila ca 30 minuter i kylen.", "Sätt ugnen på 225°C. Förgrädda pajskalet i mitten av ugnen 10 minuter.", "Pajskalet passar bra som grund till bland annat Lyxig kycklingpaj, Texmexpajer och Grön ostpaj. Här hittar du recept på Glutenfri pajdeg."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_4bb2163a-6b7d-4601-bcff-dcd3de6f11f8', 'Flygande Jacob', 4, '🍗', '["husmanskost", "kyckling", "vardag"]',
 '[{"name": "Kycklingfiléer", "amount": 4, "unit": "st"}, {"name": "Olja", "amount": 1, "unit": "tsk"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Peppar", "amount": 1, "unit": "krm"}, {"name": "Tärnat bacon", "amount": 140, "unit": "g"}, {"name": "Banan", "amount": 1, "unit": "st"}, {"name": "Matlagningsgrädde", "amount": 2.5, "unit": "dl"}, {"name": "Chilisås", "amount": 1, "unit": "dl"}, {"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Saltade jordnötter", "amount": 1, "unit": "dl"}, {"name": "Sallad", "amount": 1, "unit": "st"}]',
 '["Sätt ugnen på 225°C.", "Skär kycklingen i strimlor och bryn den i oljan i en stekpanna i omgångar, krydda med salt och peppar. Lägg i en ugnssäker form. Stek baconet och lägg på kycklingen.", "Skala och skiva bananen och lägg dem på kycklingen.", "Rör ihop grädde och chilisås, smaka av med salt och peppar. Häll det över kycklingen.", "Tillaga mitt i ugnen ca 20 minuter.", "Koka riset enligt anvisningen på förpackningen.", "Strö jordnötterna över kycklingen och servera med riset."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_1250a9b0-966d-4281-989c-03d444d1cafa', 'Våfflor grundrecept', 4, '🍽️', '["enkel", "vardag"]',
 '[{"name": "Smör", "amount": 100, "unit": "g"}, {"name": "Vetemjöl", "amount": 5, "unit": "dl"}, {"name": "Bakpulver", "amount": 1.5, "unit": "tsk"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Ägg", "amount": 2, "unit": "st"}, {"name": "Mjölk", "amount": 5, "unit": "dl"}]',
 '["Smält smöret på svag värme. Låt det svalna.", "Blanda mjöl, bakpulver och salt i en bunke.", "Vispa ner ägg och mjölk i mjölblandningen till en slät smet. Vispa i smöret.", "Hetta upp våffeljärnet. Smörj med smör till den första laggen.", "Grädda våfflorna tills de får fin färg."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_89959f4b-41f8-4f69-94b8-fa151abdd1dc', 'Busenkel broccolisoppa', 4, '🍲', '[\"enkel\", \"soppa\", \"vardag\"]',
 '[{"name": "Lök", "amount": 1, "unit": "st"}, {"name": "Potatisar", "amount": 3, "unit": "st"}, {"name": "Broccoli", "amount": 250, "unit": "g"}, {"name": "Grönsaksbuljong", "amount": 9, "unit": "dl"}, {"name": "Matlagningsgrädde", "amount": 2.5, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Bröd", "amount": 1, "unit": "st"}, {"name": "Kräftstjärtar", "amount": 1, "unit": "st"}]',
 '["Skala och skiva lök och potatis. Skär hela broccolin i bitar, även stammen.", "Koka upp buljongen och lägg i lök, potatis och broccoli. Koka upp och låt det koka i ca 10 minuter eller tills grönsakerna är mjuka. Mixa soppan med en stavmixer eller i en matberedare.", "Häll tillbaka soppan i kastrullen, tillsätt matlagningsgrädde, koka upp och smaka av med salt och peppar.", "Till servering: Servera soppan med bröd och kräftstjärtar."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_c86b2d5a-681b-4f5d-952f-8c2c81f10563', 'Kycklingwok med sweet chilisås och grönsaker', 4, '🍗', '["enkel", "kyckling", "vardag"]',
 '[{"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Gul paprika", "amount": 0.5, "unit": "st"}, {"name": "Rödlök", "amount": 1, "unit": "st"}, {"name": "Morot", "amount": 1, "unit": "st"}, {"name": "Salladslökar", "amount": 4, "unit": "st"}, {"name": "Vitlöksklyftor", "amount": 2, "unit": "st"}, {"name": "Kyckling minutstrimlor , gärna lårfilé", "amount": 550, "unit": "g"}, {"name": "Rapsolja", "amount": 2, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}, {"name": "Woksås sweet chili & garlic", "amount": 1, "unit": "förp"}, {"name": "Kruka koriander", "amount": 1, "unit": "st"}]',
 '["Koka riset enligt anvisningen på förpackningen.", "Kärna ur och strimla paprikan. Skala och skiva rödlöken. Skala och skär moroten i tunna skivor. Ansa, skölj och skär salladslöken i ca 2 cm stora bitar. Skala och riv vitlöken fint på ett rivjärn.", "Stek kycklingen i oljan i en stekpanna i omgångar tills den får färg. Lägg upp på en tallrik allt eftersom. Krydda med salt och peppar. Tillsätt grönsakerna och vitlök i några minuter i den sista stekomgången.", "Lägg tillbaka all kyckling i stekpannan. Blanda kyckling och grönsaker med woksåsen och koka sakta 3-4 minuter. Smaksätt med salt och peppar.", "Plocka bladen eller hacka koriandern grovt.", "Servera kycklingwoken med riset och toppa med koriander."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_336ba0e1-b6e6-4b17-b879-7379e7fbd398', 'Kamameshi – Japansk risgryta med kyckling och tofu', 4, '🍗', '["gryta", "kyckling", "vegetariskt"]',
 '[{"name": "Sushiris", "amount": 3, "unit": "dl"}, {"name": "Kycklingbuljong", "amount": 5, "unit": "dl"}, {"name": "Japansk soja", "amount": 3, "unit": "msk"}, {"name": "Mirin", "amount": 2, "unit": "msk"}, {"name": "Sesamolja", "amount": 1, "unit": "tsk"}, {"name": "Salt", "amount": 2, "unit": "tsk"}, {"name": "Gul lök", "amount": 1, "unit": "st"}, {"name": "Morot", "amount": 1, "unit": "st"}, {"name": "Majskorn", "amount": 1, "unit": "förp"}, {"name": "Kycklinglårfilé", "amount": 400, "unit": "g"}, {"name": "Tofu", "amount": 230, "unit": "g"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}, {"name": "Salladslökar", "amount": 3, "unit": "st"}, {"name": "Noriark", "amount": 2, "unit": "st"}, {"name": "Rostade sesamfrön", "amount": 2, "unit": "msk"}, {"name": "Gari", "amount": 1, "unit": "st"}, {"name": "Gärna snabbpicklad morot", "amount": 1, "unit": "st"}]',
 '["Skölj riset 3-4 gånger i en bunke tills vattnet är klart. Häll av riset i en sil.", "Koka upp kycklingbuljongen, gärna i en gjutjärnsgryta med lock och blanda i soja, mirin, sesamolja och salt.", "Skala och hacka löken. Skala och skär moroten i 1/2 cm stora tärningar. Häll av majsen. Skär kyckling och tofu i ca 3x3 cm stora bitar.", "Lägg i riset i grytan i buljongen och fördela lök, majs, morot, kyckling och tofu ovanpå riset. Krydda med salt och peppar.", "Koka upp och sänk därefter värmen. Låt sjuda, under lock, i ca 20 minuter, rör inte i grytan.", "Stäng av värmen och låt grytan vila ytterligare 10 minuter under lock.", "Topping: Ansa och skär salladslöken i tunna skivor på snedden. Klipp noriarken i strimlor.", "Toppa grytan med salladslök, sesamfrön och strimlad nori eller rostade sjögräschips.", "Till servering: servera gärna grytan med gari och Snabbpicklad morot."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_bc29d8af-c793-4ae3-860a-4b70882d4372', 'Enkel nudelwok med kyckling', 4, '🍗', '["enkel", "kyckling", "vardag"]',
 '[{"name": "Röd paprika", "amount": 1, "unit": "st"}, {"name": "Rödlök", "amount": 1, "unit": "st"}, {"name": "Morot", "amount": 1, "unit": "st"}, {"name": "Vitlöksklyftor", "amount": 2, "unit": "st"}, {"name": "Äggnudlar", "amount": 4, "unit": "port"}, {"name": "Sockerärtor", "amount": 0.5, "unit": "förp"}, {"name": "Rapsolja", "amount": 3, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}, {"name": "Kyckling minutstrimlor , gärna lårfilé", "amount": 550, "unit": "g"}, {"name": "Flaska woksås pad thai", "amount": 0.5, "unit": "st"}, {"name": "Kruka koriander", "amount": 1, "unit": "st"}]',
 '["Dela, kärna ur och strimla paprikan. Skala och skiva rödlöken. Skala och skär moroten i tunna skivor. Skala och riv vitlöken.", "Koka nudlarna enligt anvisningen på förpackningen. Häll av dem i ett durkslag.", "Stek grönsakerna 3-4 minuter i hälften av oljan i en stekpanna. Krydda med salt och peppar. Lägg grönsakerna på en tallrik.", "Stek kycklingen i resterande olja, i omgångar, 5 minuter per omgång. Krydda med salt och peppar.", "Lägg tillbaka grönsakerna tillsammans med kycklingen i stekpannan, tillsätt woksåsen och nudlar. Blanda ordentligt och låt det bli varmt.", "Hacka koriandern grovt och strö över woken."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_be7bc30c-f2a1-49b3-9e3e-c7dc177dba4b', 'Persiljestekt kyckling med currysås och äpple- och fänkålssallad', 4, '🍗', '["kyckling"]',
 '[{"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Kycklingfiléer", "amount": 4, "unit": "st"}, {"name": "Olja", "amount": 2, "unit": "tsk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Hackad persilja", "amount": 1, "unit": "dl"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Schalottenlökar", "amount": 2, "unit": "st"}, {"name": "Litet rött äpple", "amount": 1, "unit": "st"}, {"name": "Olja", "amount": 1, "unit": "tsk"}, {"name": "Curry", "amount": 2, "unit": "tsk"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Vatten", "amount": 1.5, "unit": "dl"}, {"name": "Kycklingbuljongtärning", "amount": 0.5, "unit": "st"}, {"name": "Matlagningsgrädde", "amount": 2.5, "unit": "dl"}, {"name": "Majsstärkelse", "amount": 1, "unit": "st"}, {"name": "Litet rött äpple", "amount": 0.5, "unit": "st"}, {"name": "Fänkål", "amount": 200, "unit": "g"}, {"name": "Olivolja", "amount": 1, "unit": "msk"}, {"name": "Vitvinsvinäger", "amount": 2, "unit": "tsk"}]',
 '["Sätt ugnen på 175°C.", "Ris: Koka riset enligt anvisningen på förpackningen.", "Kyckling: Bryn kycklingen i oljan i en stekpanna och krydda med salt och peppar.", "Hacka persiljan och pressa vitlöken. Fördela persiljan och vitlöken på kycklingen och tillaga i mitten av ugnen ca 15 minuter eller tills kycklingen har en innertemperatur på 72°C.", "Sås: Skala och hacka löken. Skala äpplet, ta bort kärnhuset och skär halva äpplet i tärningar (andra halvan sparas till salladen).", "Fräs hacket i oljan i en kastrull. Sänk värmen, tillsätt curry och pressa i vitlöken och låt fräsa någon minut.", "Rör ner vatten, smulad buljongtärning och grädde i kastrullen och sjud i 8 minuter.", "Mixa såsen slät och smaka av med salt och peppar. Red eventuellt av med lite majsstärkelse utrört i lite kallt vatten.", "Sallad: Skiva resten av äpplet tunt. Ansa och skiva fänkålen tunt, gärna på mandolin. Blanda äpple och fänkål med olivolja och vinäger och krydda med salt och peppar.", "Servera kycklingen med sås, sallad och ris."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_80f2e53f-a465-4e12-acc3-412df46d4b16', 'Kycklingcurry med ingefära', 4, '🍗', '["gryta", "kyckling"]',
 '[{"name": "Gula lökar", "amount": 2, "unit": "st"}, {"name": "Vitlöksklyftor", "amount": 3, "unit": "st"}, {"name": "Potatis", "amount": 400, "unit": "g"}, {"name": "Kycklingklubba", "amount": 4, "unit": "st"}, {"name": "Finhackad, färsk ingefära", "amount": 1.5, "unit": "msk"}, {"name": "Olivolja", "amount": 3, "unit": "msk"}, {"name": "Curry", "amount": 1.5, "unit": "msk"}, {"name": "Ketchup", "amount": 0.5, "unit": "dl"}, {"name": "Vatten", "amount": 9, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Port, kokt", "amount": 4, "unit": "st"}, {"name": "Matyoghurt", "amount": 1, "unit": "st"}, {"name": "Mango chutney", "amount": 1, "unit": "st"}]',
 '["Skala och finhacka lök och vitlök. Skala potatisen och skär i bitar.", "Dela kycklingklubborna i lår- och benbit.", "Fräs lök, vitlök och ingefära i oljan några minuter i en kastrull med lock utan att det tar färg. Tillsätt kyckling, potatis, curry och ketchup och låt fräsa några minuter.", "Tillsätt vatten så det täcker. Koka upp och sjud ca 40 minuter under lock. Vänd kycklingbitarna några gånger. Smaka av med salt.", "Koka riset enligt anvisningen på förpackningen.", "Till servering: Servera grytan med en klick yoghurt, mango chutney och ris."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_93420b58-2a4f-4ba2-b956-b526695b6ea3', 'Kyckling och sötpotatis i ugn med fetaost', 4, '🍗', '["kyckling"]',
 '[{"name": "Rödlökar", "amount": 2, "unit": "st"}, {"name": "Sötpotatis", "amount": 800, "unit": "g"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Färskpressad limejuice", "amount": 1, "unit": "msk"}, {"name": "Flytande honung", "amount": 1.5, "unit": "msk"}, {"name": "Japansk soja", "amount": 1, "unit": "msk"}, {"name": "Finriven ingefära", "amount": 2, "unit": "msk"}, {"name": "Kycklinglårfilé", "amount": 600, "unit": "g"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Olivolja", "amount": 3, "unit": "msk"}, {"name": "Fetaost", "amount": 150, "unit": "g"}, {"name": "Skivad färsk", "amount": 1, "unit": "st"}]',
 '["Sätt ugnen på 225°C.", "Skala löken och tvätta sötpotatisen. Skär lök och sötpotatis i klyftor och lägg på en plåt.", "Skala och finhacka vitlöken, skala och riv ingefäran och blanda med limejuice, honung och soja. Blanda med kycklingen och lägg på plåten. Krydda kycklingen och grönsakerna med salt och ringla över oljan. Rosta i mitten av ugnen ca 25 minuter tills sötpotatisen fått färg och kycklingen är genomstekt och har en innertemperatur på 72°C.", "Toppa med smulad fetaost och jalapeño."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_b21ee60b-0c71-485e-829e-adfb8cabdecd', 'Kycklingsallad med mozzarella och basilikadressing', 4, '🍗', '["kyckling", "sallad"]',
 '[{"name": "Pumpakärnor", "amount": 0.5, "unit": "dl"}, {"name": "Kycklinglårfilé", "amount": 500, "unit": "g"}, {"name": "Matolja", "amount": 1, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}, {"name": "Kruka krispsallad", "amount": 1, "unit": "st"}, {"name": "Körsbärstomater", "amount": 250, "unit": "g"}, {"name": "Gul paprika", "amount": 1, "unit": "st"}, {"name": "Silverlök", "amount": 0.5, "unit": "st"}, {"name": "Vitvinsvinäger", "amount": 2, "unit": "msk"}, {"name": "Olivolja", "amount": 1, "unit": "dl"}, {"name": "Kruka basilika", "amount": 1, "unit": "st"}, {"name": "Babyspenat", "amount": 65, "unit": "g"}, {"name": "Mozzarella", "amount": 2, "unit": "förp"}, {"name": "Bröd", "amount": 1, "unit": "st"}]',
 '["Rosta pumpakärnorna hastigt i en torr stekpanna, lägg upp på en tallrik.", "Stek eller grilla kycklingen i oljan i stekpannan, 4-5 minuter på varje sida, eller tills kycklingen har en innertemperatur på 72°C. Krydda med salt och peppar. Lägg kycklingen på en tallrik.", "Ansa och lossa salladsbladen från varandra. Dela tomaterna i halvor. Dela, kärna ur och strimla paprikan. Skala och skiva löken mycket tunt, gärna på en mandolin.", "Blanda vinäger och olivolja. Hacka basilikan fint och rör ner i dressingen. Smaksätt med salt och peppar.", "Skär kycklingen i skivor eller strimlor.", "Lägg sallad, spenat, tomater, paprika, lök och kyckling på ett fat.", "Häll av mozzarellaosten och bryt den över salladen. Ringla dressingen över salladen och toppa med pumpakärnor.", "Till servering: Servera gärna surdegsbröd till kycklingsalladen."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_14a97950-21c7-4af9-8cd2-2d359c0eda6e', 'Bacongratinerad kyckling', 4, '🍗', '["kyckling"]',
 '[{"name": "Kycklingfiléer", "amount": 4, "unit": "st"}, {"name": "Olja", "amount": 1, "unit": "tsk"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Peppar", "amount": 1, "unit": "krm"}, {"name": "Tärnat bacon", "amount": 140, "unit": "g"}, {"name": "Matlagningsgrädde", "amount": 2.5, "unit": "dl"}, {"name": "Chilisås", "amount": 1, "unit": "dl"}, {"name": "Curry", "amount": 1, "unit": "tsk"}, {"name": "Paprikapulver", "amount": 1, "unit": "tsk"}, {"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Morötter", "amount": 500, "unit": "g"}]',
 '["Tina kycklingen om fryst används.", "Sätt ugnen på 225°C.", "Bryn kycklingen i oljan i en stekpanna i omgångar, krydda med salt och peppar. Lägg i en ugnsform.", "Stek baconet och lägg upp på en tallrik.", "Rör ihop grädde och chilisås i stekpannan och låt det bli lite varmt, smaka av med curry, paprikapulver, salt och peppar.", "Häll såsen över kycklingen. Toppa med baconet.", "Tillaga i mitten av ugnen ca 20 minuter eller tills kycklingen har en innertemperatur på 72°C.", "Koka riset enligt anvisningen på förpackningen.", "Skala morötterna och skär dem i stavar eller riv dem.", "Servera kycklingen med ris och morötter."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_d3ac474b-7044-4d74-9cf9-1eea21a79993', 'Kyckling med ajvartäcke', 4, '🍗', '["kyckling", "vegetariskt"]',
 '[{"name": "Kycklinglårfilé", "amount": 600, "unit": "g"}, {"name": "Olja", "amount": 2, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Lätt crème fraiche", "amount": 2, "unit": "dl"}, {"name": "Ajvar relish", "amount": 1.5, "unit": "dl"}, {"name": "Riven lagrad ost", "amount": 1, "unit": "dl"}, {"name": "Riven vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Svartpeppar", "amount": 1, "unit": "krm"}, {"name": "Panko", "amount": 1, "unit": "dl"}, {"name": "Olja", "amount": 2, "unit": "msk"}, {"name": "Fryst hackad persilja", "amount": 2, "unit": "msk"}, {"name": "Sallad", "amount": 1, "unit": "st"}, {"name": "Kokta gröna bönor", "amount": 1, "unit": "st"}, {"name": "Kokt potatis ris", "amount": 1, "unit": "st"}]',
 '["Sätt ugnen på 225°C.", "Kyckling: Bryn kycklingen hastigt runtom i olja, krydda med salt och peppar. Lägg i en ugnsform.", "Ajvarsås: Blanda crème fraiche, ajvar relish, ost, vitlök, salt och peppar. Bred över kycklingen.", "Blanda panko med olja och persilja och strö över.", "Gratinera ca 25 minuter.", "Till servering: Servera gärna med en sallad och kokta gröna bönor eller ev potatis, ris eller annat gryn."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_81a7f6a8-7f75-4cb1-99c6-f7499143da7f', 'Kycklinglasagne med tomat och mozzarella', 4, '🍗', '["gratäng", "kyckling", "pasta"]',
 '[{"name": "Gula lökar", "amount": 2, "unit": "st"}, {"name": "Morötter", "amount": 2, "unit": "st"}, {"name": "Vitlöksklyftor", "amount": 2, "unit": "st"}, {"name": "Kycklinglårfilé", "amount": 600, "unit": "g"}, {"name": "Olivolja", "amount": 2, "unit": "msk"}, {"name": "Tomatpuré", "amount": 3, "unit": "msk"}, {"name": "Krossade tomater", "amount": 1, "unit": "förp"}, {"name": "Vatten", "amount": 3, "unit": "dl"}, {"name": "Hönsbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Kruka basilika", "amount": 1, "unit": "st"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Svartpeppar", "amount": 1, "unit": "krm"}, {"name": "Lasagneplattor", "amount": 10, "unit": "st"}, {"name": "Mozzarella", "amount": 2, "unit": "förp"}]',
 '["Sätt ugnen på 175˚C.", "Skala lök och morötter och skär dem i tärningar, 1x1 cm. Skala och finhacka vitlöken.", "Strimla kycklinglårfilén. Bryn i olivolja i en stekpanna med höga kanter. Tillsätt lök, vitlök och morötter och låt det bryna med någon minut. Tillsätt tomatpuré.", "Tillsätt krossade tomater, vatten och smulad buljongtärning. Låt koka i 10 minuter. Strimla basilika och tillsätt tillsammans med salt och peppar.", "Skiva mozzarellan.", "Häll lite fyllning i botten av en ugnsform, 20x30 cm. Lägg på lasagneplattor. Varva fyllning och lasagneplattor. Lägg hälften av mozzarellan på et lager i mitten. Avsluta med fyllning och toppa med resten av mozzarellan.", "Sätt in i mitten av ugnen i ca 25 minuter. Servera med grönsallad."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_d0ba0d47-dbf3-4719-99e0-6299771ffd5e', 'Lyxig kycklingpaj', 8, '🍗', '["kyckling"]',
 '[{"name": "Kyld pajdeg", "amount": 1, "unit": "förp"}, {"name": "Grillad kyckling", "amount": 0.5, "unit": "st"}, {"name": "Gul lök", "amount": 1, "unit": "st"}, {"name": "Vitlöksklyftor", "amount": 2, "unit": "st"}, {"name": "Röd paprika", "amount": 1, "unit": "st"}, {"name": "Zucchini", "amount": 0.5, "unit": "st"}, {"name": "Olivolja", "amount": 1, "unit": "msk"}, {"name": "Strimlade soltorkade tomater", "amount": 1, "unit": "dl"}, {"name": "Finstrimlad persilja", "amount": 3, "unit": "msk"}, {"name": "Riven parmesan", "amount": 2, "unit": "dl"}, {"name": "Flingsalt", "amount": 0.5, "unit": "tsk"}, {"name": "Svartpeppar", "amount": 1, "unit": "krm"}, {"name": "Ägg", "amount": 3, "unit": "st"}, {"name": "Riven ost", "amount": 2.5, "unit": "dl"}, {"name": "Mjölk", "amount": 2, "unit": "dl"}, {"name": "Vispgrädde", "amount": 1, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Marinerade, gärna kärnfria, oliver", "amount": 1.5, "unit": "dl"}, {"name": "Marinerade kronärtskockor", "amount": 1, "unit": "förp"}, {"name": "Färsk basilika", "amount": 1, "unit": "st"}]',
 '["Fyllning: Plocka och skär kycklingköttet i tärningar.", "Skala och finhacka lök och vitlök. Dela och kärna ur paprikan. Skär paprika och zucchini i cm-stora bitar.", "Fräs lök, zucchini och paprika i olja i en stekpanna ca 5 minuter. Ta från värmen.", "Blanda i kyckling, tomaterna, persilja, parmesan och salt och peppar.", "Äggstanning: Vispa ihop ägg, riven ost, mjölk, grädde och salt.", "Rulla ut pajdegen i en pajform ca 25 cm i diameter (för 4 port) eller gör en egen hemmagjord pajdeg. Förgrädda pajskalet enligt anvisningen på förpackningen.", "Sätt ugnen på 200°C.", "Varva 2-3 lager med kycklingfyllning (för 1 paj) och äggsmet i det förgräddade pajskalet.", "Grädda pajen ca 30 minuter i mitten av ugnen eller tills äggsmeten har stannat och pajen fått fin färg.", "Topping: Toppa med oliver, basilika och gärna kronärtskockor vid servering."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_396d8358-5c6c-4155-be7f-041c8c820f1c', 'Allt på en plåt med pumpa och kyckling', 6, '🍗', '["kyckling", "vegetariskt"]',
 '[{"name": "Butternutpumpa", "amount": 1, "unit": "st"}, {"name": "Morötter", "amount": 4, "unit": "st"}, {"name": "Olivolja", "amount": 4, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}, {"name": "Kycklinglårfilé", "amount": 500, "unit": "g"}, {"name": "Skuren färsk", "amount": 150, "unit": "g"}, {"name": "Basilikapesto", "amount": 1, "unit": "förp"}, {"name": "Kokta stora vita bönor", "amount": 1, "unit": "förp"}, {"name": "Finriven parmesan", "amount": 1, "unit": "dl"}, {"name": "Crème fraiche", "amount": 2, "unit": "dl"}]',
 '["Sätt ugnen på 225°C och sätt in en långpanna i ugnen.", "Skala, kärna ur och skär pumpan i ca 3 x 3 cm stora bitar. Ansa och skär morötterna i lika stora bitar.", "Blanda pumpa och morötter med olivolja i en bunke och smaksätt med salt och peppar.", "Lägg grönsakerna (ej grönkål och bönor) i den förvärmda långpannan. Sätt in i mitten av ugnen i först 15 minuter.", "Dela kycklinglårfilén i halvor. Blanda kycklingen och grönkålen med peston i en bunke. Krydda med salt och peppar.", "Ta ut långpannan och fördela kyckling och grönkål över grönsakerna i långpannan. Sätt in i ugnen igen i 10 minuter.", "Häll bönorna i ett durkslag, spola dem i kallt vatten och låt rinna av. Ta ut långpannan och lägg bönorna på grönsaker och kyckling. Sätt in i ugnen igen i ytterligare 10 minuter, eller tills grönsakerna är mjuka och kycklingen har en innertemperatur på 72°C.", "Parmesankräm: Riv parmesanosten fint på ett rivjärn. Blanda osten med crème fraiche. Smaka av med salt och peppar.", "Servera grönsaker och kyckling med parmesankrämen."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_423cece5-ae82-4ae5-a8c5-a36780c8e801', 'Nasi goreng', 4, '🍗', '["kyckling"]',
 '[{"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Schalottenlökar", "amount": 2, "unit": "st"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Morötter", "amount": 2, "unit": "st"}, {"name": "Salladskål", "amount": 150, "unit": "g"}, {"name": "Kycklingfiléer", "amount": 4, "unit": "st"}, {"name": "Olja", "amount": 3, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Ketjap manis", "amount": 2, "unit": "msk"}, {"name": "Tomatpuré", "amount": 1, "unit": "msk"}, {"name": "Sambal oelek", "amount": 1, "unit": "tsk"}, {"name": "Ägg", "amount": 4, "unit": "st"}, {"name": "Olja", "amount": 2, "unit": "tsk"}, {"name": "Lime", "amount": 1, "unit": "st"}, {"name": "Salladslökar", "amount": 3, "unit": "st"}]',
 '["Koka riset enligt anvisningen på förpackningen.", "Skala och skiva schalottenlök, vitlök och morötter. Strimla kålen tunt.", "Strimla kycklingen och stek den och grönsakerna i omgångar i hälften av oljan i en stor stekpanna. Krydda med salt och peppar.", "Lägg upp fräset på en tallrik och stek sedan det färdigkokta riset i resten av oljan. Blanda ner ketjap manis, tomatpuré och sambal oelek och låt fräsa någon minut till. Sänk värmen och rör i kycklingfräset.", "Stek äggen i oljan i en stekpanna.", "Skär limen i klyftor och strimla salladslöken.", "Strö salladslöken över nasi gorengen och servera med ägg och limeklyftor."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_b75f0d49-bf78-4586-b5e6-6c6e9d520fbe', 'Citron- och olivbakad kyckling', 4, '🍗', '["gryta", "kyckling"]',
 '[{"name": "Fasta potatisar", "amount": 8, "unit": "st"}, {"name": "Gula lökar", "amount": 2, "unit": "st"}, {"name": "Vitlöksklyftor", "amount": 3, "unit": "st"}, {"name": "Kycklinglårfilé", "amount": 600, "unit": "g"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Neutral rapsolja", "amount": 1, "unit": "msk"}, {"name": "Vitt vin", "amount": 3, "unit": "dl"}, {"name": "Gröna oliver med kärnor", "amount": 1.5, "unit": "dl"}, {"name": "Kapris", "amount": 4, "unit": "msk"}, {"name": "Citron", "amount": 1, "unit": "st"}, {"name": "Olivolja", "amount": 3, "unit": "msk"}, {"name": "Körsbärstomater", "amount": 150, "unit": "g"}, {"name": "Kruka persilja", "amount": 1, "unit": "st"}, {"name": "Aioli", "amount": 1, "unit": "st"}]',
 '["Sätt ugnen på 200°C.", "Skölj och skär potatisen ca 3x3 cm stora bitar. Skala och skär löken i klyftor, skala och skiva vitlöken.", "Krydda kycklingen med salt och bryn den runtom i oljan i en gryta som tål att stå i ugn. Ta upp kycklingen.", "Lägg potatis, lök och vitlök i grytan, lägg tillbaka kycklingen överst. Tillsätt vin.", "Häll av oliver och kapris. Skala citronen med potatisskalare, se till att inte få med det vita bittra skalet. Lägg citronskalen i grytan och tillsätt olivolja, oliver, kapris och tomater.", "Sätt på locket på grytan och sätt in i mitten av ugnen ca 45 minuter.", "Hacka persiljan.", "Till servering: Blanda ner persiljan i grytan och servera, gärna med Aioli."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_b4d2f695-6290-4724-bc5a-de87bf7366d3', 'Fransk kycklinggryta', 4, '🍗', '["gryta", "kyckling", "vegetariskt"]',
 '[{"name": "Rödlök", "amount": 1, "unit": "st"}, {"name": "Rödvinsvinäger", "amount": 1, "unit": "msk"}, {"name": "Strösocker", "amount": 0.5, "unit": "msk"}, {"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Torrsaltat bacon", "amount": 140, "unit": "g"}, {"name": "Kycklingfiléer", "amount": 4, "unit": "st"}, {"name": "Olivolja", "amount": 1, "unit": "tsk"}, {"name": "Dragon", "amount": 1, "unit": "tsk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Vitt matlagningsvin", "amount": 1, "unit": "dl"}, {"name": "Crème fraiche", "amount": 2, "unit": "dl"}, {"name": "Dijonsenap", "amount": 2, "unit": "msk"}, {"name": "Haricots verts", "amount": 150, "unit": "g"}]',
 '["Skala och skiva löken i tunna ringar. Blanda vinäger och socker i en skål och vänd ner löken.", "Koka riset enligt anvisningen på förpackningen.", "Strimla och stek bacon i en stekpanna, lägg upp på en tallrik.", "Gryta: Skär kycklingen i skivor och bryn dem i olivolja i en stekpanna. Krydda med dragon, salt och peppar. Rör i vinet och koka upp. Sänk värmen och rör i crème fraiche och koka 6-8 minuter. Rör ner senap och smaka av med salt och peppar.", "Till servering: Ansa och koka haricots verts i saltat vatten.", "Servera kycklingcasserolen med bacon, lök, haricots verts och ris."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_e7bb0ca8-86d8-4e4f-8367-c3e450d6de61', 'Matig macka med kyckling, avokado och mozzarella', 2, '🍗', '["kyckling"]',
 '[{"name": "Tomat", "amount": 1, "unit": "st"}, {"name": "Avokado", "amount": 1, "unit": "st"}, {"name": "Mozzarella", "amount": 1, "unit": "st"}, {"name": "Basilikapesto", "amount": 4, "unit": "msk"}, {"name": "Grovt bröd", "amount": 4, "unit": "skivor"}, {"name": "Skivad inlagd jalapeño", "amount": 2, "unit": "msk"}, {"name": "Skivad kyckling gärna", "amount": 1, "unit": "förp"}, {"name": "Tabasco", "amount": 4, "unit": "krm"}, {"name": "Kruka basilikablad", "amount": 0.25, "unit": "st"}, {"name": "Matolja", "amount": 1, "unit": "msk"}]',
 '["Skiva tomaten. Dela, ta ur kärnan och gröp ur avokadon och skiva den. Häll av och skiva mozzarellan.", "Bred pesto på alla 4 bröden.", "Fördela tomat, avokado, mozzarella, jalapeño och kycklingskivor på brödbottnarna. Droppa på 2 krm tabasco över fyllningen på varje macka, lägg på några basilikablad. Lägg på brödlocket och tryck till. Pensla båda brödsidorna med olja.", "Grilla eller stek mackorna sakta, 4-5 minuter på varje sida."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_299959a1-f0be-4b0d-9aaa-7194f5d9f03a', 'Stekt kyckling med krämig kålsallad', 4, '🍗', '["kyckling"]',
 '[{"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Majonnäs", "amount": 0.5, "unit": "dl"}, {"name": "Lätt crème fraiche", "amount": 2, "unit": "dl"}, {"name": "Vitlöksklyfta", "amount": 0.5, "unit": "st"}, {"name": "Curry", "amount": 1, "unit": "tsk"}, {"name": "Sweet chili", "amount": 2, "unit": "msk"}, {"name": "Pak choi", "amount": 250, "unit": "g"}, {"name": "Salladslökar", "amount": 2, "unit": "st"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Kycklingfilé", "amount": 600, "unit": "g"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Sesamfrön", "amount": 1, "unit": "msk"}]',
 '["Tina kycklingen (om fryst används).", "Koka riset enligt anvisningen på förpackningen.", "Blanda majonnäs och crème fraiche och pressa i vitlöken. Krydda med curry och sweet chili.", "Skölj pak choien och låt den rinna av ordentligt. Strimla kålen och salladslöken fint. Vänd ner i såsen och smaka av med salt och peppar.", "Dela varje kycklingfilé i tre delar på längden. Stek kycklingen i oljan i en stekpanna ca 10 minuter, vänd då och då. Krydda med salt och peppar.", "Servera kycklingen med ris och den krämiga kålsalladen, toppad med sesamfrö."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_996bf0c7-247c-4457-9bd0-07e021d4ed19', 'Gul currygryta med kokosmjölk', 4, '🍗', '["gryta", "kyckling"]',
 '[{"name": "Gul lök", "amount": 1, "unit": "st"}, {"name": "Morot", "amount": 1, "unit": "st"}, {"name": "Strimlad kycklingfilé", "amount": 600, "unit": "g"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Curry", "amount": 1, "unit": "msk"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Kokosmjölk", "amount": 400, "unit": "ml"}, {"name": "Kycklingbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Äggnudlar", "amount": 4, "unit": "port"}, {"name": "Sockerärtor", "amount": 150, "unit": "g"}, {"name": "Körsbärstomater", "amount": 12, "unit": "st"}]',
 '["Sätt på en kastrull med vatten till nudlarna.", "Skala och skär lök och morot i strimlor. Fräs lök, morot och kyckling i oljan i en gryta. Krydda med curry och salt.", "Tillsätt kokosmjölk och smula ner buljongtärningen. Låt grytan koka 5 minuter.", "Koka nudlarna och sockerärterna enligt anvisningen på nudelförpackningen.", "Dela tomaterna i halvor.", "Servera grytan med nudlarna, tomaterna och sockerärtorna."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_8d78cdc0-e2b1-4c07-821a-e7ff2c0e6552', 'Chicken à la king', 4, '🍗', '["kyckling"]',
 '[{"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Gul lök", "amount": 1, "unit": "st"}, {"name": "Färska champinjoner", "amount": 250, "unit": "g"}, {"name": "Röda", "amount": 2, "unit": "st"}, {"name": "Kycklinglårfilé", "amount": 500, "unit": "g"}, {"name": "Smör", "amount": 3, "unit": "msk"}, {"name": "Vispgrädde", "amount": 3, "unit": "dl"}, {"name": "Vatten", "amount": 2.5, "unit": "dl"}, {"name": "Hönsbuljongtärning", "amount": 1.5, "unit": "st"}, {"name": "Majsstärkelse", "amount": 4, "unit": "tsk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}, {"name": "Citron", "amount": 0.5, "unit": "st"}, {"name": "Kruka persilja", "amount": 1, "unit": "st"}, {"name": "Gärna sallad", "amount": 1, "unit": "st"}]',
 '["Koka riset enligt anvisning på förpackningen.", "Skala och finhacka löken. Ansa och skiva champinjonerna. Dela, kärna ur och skär paprikan i ca 2 cm stora tärningar.", "Dela kycklinglåren i 4 bitar.", "Stek svamp och lök i smöret i en stor gryta. När svampen börjar få färg, tillsätt kycklingen. Rör runt kycklingen.", "Tillsätt grädde, vatten, smulad buljongtärning och paprika. Koka i ca 10 minuter.", "Rör ut majsstärkelsen med lite kallt vatten och tillsätt i kycklinggrytan under omröring.", "Smaka av grytan med salt, peppar och några droppar citronsaft.", "Hacka persiljan.", "Till servering: Servera grytan, toppad med persilja och med ris och gärna sallad."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_af24df27-7331-4c54-90cc-7f254c1ab125', 'Kyckling i dragonsås med kabanoss och rostad potatis', 4, '🍗', '["kyckling"]',
 '[{"name": "Potatis", "amount": 900, "unit": "g"}, {"name": "Zucchini", "amount": 1, "unit": "st"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Kabanoss", "amount": 300, "unit": "g"}, {"name": "Kycklingfilé", "amount": 300, "unit": "g"}, {"name": "Smör", "amount": 2, "unit": "tsk"}, {"name": "Crème fraiche", "amount": 2, "unit": "dl"}, {"name": "Torkad dragon", "amount": 2, "unit": "tsk"}, {"name": "Mjölk", "amount": 1, "unit": "dl"}, {"name": "Vitvinsvinäger", "amount": 1, "unit": "tsk"}]',
 '["Sätt ugnen på 225°C och sätt in en plåt.", "Skär potatisen i klyftor eller halvor och zucchinin i stora bitar. Blanda potatis och zucchini med oljan och krydda med salt och peppar. Häll ut potatis och zucchini på den varma plåten och sätt in mitt i ugnen ca 25 minuter.", "Skär korven och kycklingen i ca 1 cm tjocka skivor och stek dem i smöret i en stekpanna, några minuter på varje sida. Krydda med salt och peppar.", "Rör ner crème fraiche, dragon och mjölk och låt sjuda någon minut. Smaka av med vinäger, salt och peppar.", "Servera potatis och zucchini med kycklingsåsen."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_91259230-36e0-4bb8-937a-8fcd32efc265', 'Cassoulet på kyckling och bondbönor', 6, '🍗', '["kyckling", "vegetariskt"]',
 '[{"name": "Rimmat sidfläsk", "amount": 375, "unit": "g"}, {"name": "Gula lökar", "amount": 2, "unit": "st"}, {"name": "Vitlöksklyftor", "amount": 3, "unit": "st"}, {"name": "Olja", "amount": 2, "unit": "msk"}, {"name": "Tomatpuré", "amount": 3, "unit": "msk"}, {"name": "Vitt matlagningsvin", "amount": 2.5, "unit": "dl"}, {"name": "Kycklinglårfilé", "amount": 700, "unit": "g"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Kokta vita bönor", "amount": 1, "unit": "förp"}, {"name": "Vatten", "amount": 3, "unit": "dl"}, {"name": "Torkad timjan", "amount": 1, "unit": "tsk"}, {"name": "Torkad rosmarin", "amount": 1, "unit": "tsk"}, {"name": "Kycklingbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Färska bondbönor i skida", "amount": 750, "unit": "g"}, {"name": "Potatis, ris", "amount": 1, "unit": "st"}]',
 '["Skär det rimmade fläsket i mindre bitar. Skala och hacka lök och vitlök.", "Fräs fläsk, lök och vitlök i en stor gryta i hälften av oljan. Tillsätt tomatpuré och låt fräsa ytterligare några minuter. Tillsätt vinet och låt koka kraftigt i någon minut. Sänk därefter värmen.", "Bryn kycklingen i resten av oljan i en stekpanna, krydda med salt och peppar och lägg över i grytan.", "Häll bönorna i ett durkslag, spola dem i kallt vatten och låt rinna av.", "Rör ner bönor, vatten, timjan, rosmarin och smulad buljongtärning i grytan och låt den koka upp och sjuda ca 30 minuter utan lock.", "Ta ur bönorna ur bondbönsskidorna. Koka bönorna i saltat vatten ca 4 minuter. Ta ur bönorna ur det sega, vita skalet och tillsätt i grytan. Smaka av grytan med salt och peppar.", "Servera gärna grytan med potatis, ris eller bröd."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_be494d91-3150-467d-8a8b-02f8b5bf5ccc', 'Pasta med makrill i tomatsås', 4, '🐟', '["fisk", "pasta"]',
 '[{"name": "Vitlöksklyftor", "amount": 2, "unit": "st"}, {"name": "Olivolja", "amount": 3, "unit": "msk"}, {"name": "Chiliflakes", "amount": 0.5, "unit": "tsk"}, {"name": "Finrivet citronskal", "amount": 1, "unit": "msk"}, {"name": "Hackad kapris", "amount": 3, "unit": "msk"}, {"name": "Makrillfilé i tomatsås", "amount": 2, "unit": "förp"}, {"name": "Spaghetti", "amount": 400, "unit": "g"}, {"name": "Finhackad persilja", "amount": 1, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}, {"name": "Finriven parmesan", "amount": 1, "unit": "st"}, {"name": "Citronklyftor", "amount": 1, "unit": "st"}]',
 '["Skala och hacka vitlöken. Fräs vitlöken i oljan några minuter i en stekpanna. Tillsätt chiliflakes, citronskal och kapris och fräs ytterligare några minuter.", "Bryt makrillen i bitar och lägg ner tillsammans med tomatsåsen.", "Koka pastan enligt anvisning på förpackningen. Häll av och spar 1 dl av kokvattnet (för 4 port). Tillsätt pastan, kokvattnet och persiljan i stekpannan och blanda. Smaka av med salt och peppar.", "Till servering: Toppa med riven parmesan och servera med citronklyftor."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_11458904-2f21-4c1a-bedc-1062b05c3f55', 'Frasig citrontorsk med potatismos och pistagepesto', 4, '🐟', '["fisk"]',
 '[{"name": "Fast potatis", "amount": 1, "unit": "kg"}, {"name": "Mjölk", "amount": 3, "unit": "dl"}, {"name": "Smör", "amount": 75, "unit": "g"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Finriven parmesan", "amount": 0.5, "unit": "dl"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Kruka basilika", "amount": 1, "unit": "st"}, {"name": "Lättrostade pistagenötter", "amount": 2, "unit": "msk"}, {"name": "Olivolja", "amount": 0.5, "unit": "dl"}, {"name": "Torskryggfilé", "amount": 4, "unit": "port"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Citron", "amount": 1, "unit": "st"}, {"name": "Kruka dill", "amount": 0.5, "unit": "st"}, {"name": "Panko", "amount": 1.5, "unit": "dl"}, {"name": "Ägg", "amount": 1, "unit": "st"}, {"name": "Smör", "amount": 50, "unit": "g"}, {"name": "Neutral rapsolja", "amount": 2, "unit": "msk"}]',
 '["Tina torsken.", "Potatismos: Skala och koka potatisen i saltat vatten.", "Pistagepesto: Riv parmesanen fint på ett rivjärn och skala vitlöken. Mixa ihop basilika, nötter, parmesan, vitlök och olja till en pesto.", "Potatismos: Häll av potatisen och låt ånga av i durkslag. Värm mjölk och smör i en gryta. Pressa i potatisen med potatispress. Vispa till ett mos med en ballongvisp. Smaka av med salt och peppar.", "Fisk: Salta torsken. Riv yttersta skalet fint av citronen och skär den sedan i klyftor. Hacka dillen.", "Blanda citronskalet med panko och dillen på en tallrik. Vispa upp ägget i en annan tallrik. Vänd torsken i ägget och sedan i pankon.", "Stek torsken frasig och gyllenbrun i smör och olja i en stor stekpanna ca 3 minuter per sida.", "Servera fisken med mos, pesto och citronklyftor."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_f05c6a63-ff10-440e-adbb-bca6cbd19b73', 'Tonfisksallad med kikärtor och dijonnaise', 4, '🐟', '["fisk", "sallad", "vegetariskt"]',
 '[{"name": "Kokta kikärtor", "amount": 1, "unit": "förp"}, {"name": "Olja", "amount": 3, "unit": "msk"}, {"name": "Chilipulver", "amount": 1, "unit": "tsk"}, {"name": "Salt", "amount": 2, "unit": "krm"}, {"name": "Majonnäs", "amount": 1, "unit": "dl"}, {"name": "Dijonsenap", "amount": 2, "unit": "msk"}, {"name": "Finrivet citronskal", "amount": 1, "unit": "msk"}, {"name": "Färskpressad citronjuice", "amount": 3, "unit": "msk"}, {"name": "Svartpeppar", "amount": 0.5, "unit": "tsk"}, {"name": "Gurka", "amount": 1, "unit": "st"}, {"name": "Endive", "amount": 2, "unit": "st"}, {"name": "Tonfisk i olja", "amount": 2, "unit": "förp"}, {"name": "Finskuren gräslök", "amount": 0.5, "unit": "dl"}]',
 '["Häll kikärtorna i ett durkslag, spola dem i kallt vatten och låt rinna av. Torka dem torra på hushållspapper. Stek kikärtorna i oljan i en stekpanna på medel­värme tills de är gyllene. ­Krydda med chilipulver och salt.", "Rör ihop majonnäs, senap, citronskal och -juice och peppar.", "Skär gurkan i bitar. Plocka bladen från salladen och skölj. Häll av tonfisken.", "Lägg upp allt på ett fat, ringla över dressingen och strö över gräslöken."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_df6c7f5b-bfea-4b0e-8ff6-3d3a30487d20', 'Laxpytt med gulbetor och kräm på Västerbottensost', 4, '🐟', '["fisk", "lax"]',
 '[{"name": "Potatis", "amount": 500, "unit": "g"}, {"name": "Gulbetor", "amount": 500, "unit": "g"}, {"name": "Olivolja", "amount": 0.5, "unit": "dl"}, {"name": "Fänkålsfrö", "amount": 1.5, "unit": "tsk"}, {"name": "Gula lökar", "amount": 2, "unit": "st"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Gräddfil", "amount": 3, "unit": "dl"}, {"name": "Riven Västerbottensost", "amount": 1.5, "unit": "dl"}, {"name": "Fänkål", "amount": 1, "unit": "st"}, {"name": "Citron", "amount": 0.5, "unit": "st"}, {"name": "Kruka dill", "amount": 1, "unit": "st"}, {"name": "Kallrökt lax i bit", "amount": 400, "unit": "g"}]',
 '["Sätt ugnen på 100°C och sätt in en långpanna.", "Skala potatis och gulbetor och skär dem i tärningar. Blanda tärningarna med oljan och mortla och strö över fänkålsfröna. Skala och hacka löken grovt.", "Stek i potatis- och gulbetstärningarna mjuka i en stekpanna i omgångar, krydda med salt och peppar. Tillsätt löken i slutet av stekningen. Varmhåll de färdigstekta grönsakerna, allt eftersom, i långpannan i ugnen.", "Ostkräm: Blanda gräddfilen med osten och smaka av med salt och peppar.", "Topping: Ansa och hyvla fänkålen tunt, gärna på mandolin. Riv över citronskalet och pressa över saften. Hacka och blanda ner hälften av dillen.", "Skär laxen i kuber.", "Toppa pytten med fänkål, lax och resten av dillen och servera med ostkrämen."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_9c810f00-398d-4f37-9113-0b1081961df5', 'Lax med gult kokosris och salladslök', 4, '🐟', '["fisk", "lax"]',
 '[{"name": "Gul lök", "amount": 1, "unit": "st"}, {"name": "Rapsolja", "amount": 1, "unit": "msk"}, {"name": "Basmatiris", "amount": 3, "unit": "dl"}, {"name": "Gurkmeja", "amount": 2, "unit": "tsk"}, {"name": "Kokosmjölk", "amount": 1, "unit": "förp"}, {"name": "Vatten", "amount": 3, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Laxfilé utan skinn", "amount": 500, "unit": "g"}, {"name": "Japansk soja", "amount": 2, "unit": "msk"}, {"name": "Sesamolja", "amount": 1, "unit": "tsk"}, {"name": "Salladslök", "amount": 1, "unit": "förp"}, {"name": "Smör", "amount": 25, "unit": "g"}, {"name": "Vatten", "amount": 3, "unit": "msk"}, {"name": "Färsk koriander", "amount": 1, "unit": "st"}, {"name": "Rostad lök", "amount": 1, "unit": "st"}, {"name": "Srirachasås", "amount": 1, "unit": "st"}]',
 '["Skala och finhacka löken. Fräs den i oljan i en vid kastrull med lock tills den mjuknar. Tillsätt riset och fräs lite till. Tillsätt gurkmeja, kokosmjölk, vatten och salt och låt koka upp. Koka på svag värme under lock ca 15 minuter.", "Skär laxen i tärningar och blanda med soja och sesamolja. Låt stå 5–10 minuter. Skiva salladslöken.", "Sprid ut laxen och salladslöken på riset. Klicka över smör och häll på 3 msk vatten (för 4 port). Ånga under lock på låg värme ca 10 minuter eller tills laxen har en innertemperatur på 54°C.", "Till servering: Servera med koriander, rostad lök och sriracha."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_40450563-2e6c-45cf-b6ff-f31f3964ceab', 'Hot tuna pasta', 4, '🐟', '["fisk", "pasta"]',
 '[{"name": "Pasta", "amount": 4, "unit": "port"}, {"name": "Rödlök", "amount": 1, "unit": "st"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Olja", "amount": 2, "unit": "tsk"}, {"name": "Tonfisk i vatten", "amount": 3, "unit": "förp"}, {"name": "Crème fraiche", "amount": 2, "unit": "dl"}, {"name": "Mjölk", "amount": 0.5, "unit": "dl"}, {"name": "Chiliflakes", "amount": 1, "unit": "krm"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Plommontomater", "amount": 0.5, "unit": "förp"}, {"name": "Majskorn", "amount": 1, "unit": "förp"}]',
 '["Koka pastan enligt anvisningen på förpackningen.", "Skala och hacka löken.", "Fräs löken i oljan i en stekpanna och pressa i vitlöken. Sänk värmen och rör i tonfisk, crème fraiche och mjölk. Krydda med chiliflakes och smaka av med salt och peppar.", "Skär tomaterna i bitar.", "Servera pastan med tonfisksåsen, majs och tomater."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_62f277e1-9e8e-4f4a-a3fb-7630c1b9e765', 'Laxlasagne med fetaost', 4, '🐟', '["fisk", "lax", "pasta"]',
 '[{"name": "Fryst bladspenat", "amount": 400, "unit": "g"}, {"name": "Fetaost", "amount": 150, "unit": "g"}, {"name": "Cottage cheese", "amount": 500, "unit": "g"}, {"name": "Vitlöksklyftor", "amount": 2, "unit": "st"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Vitpeppar", "amount": 1, "unit": "st"}, {"name": "Skinn- och benfri laxfilé", "amount": 400, "unit": "g"}, {"name": "Krossade tomater med örter t ex basilika", "amount": 1, "unit": "förp"}, {"name": "Vitt vin", "amount": 0.5, "unit": "dl"}, {"name": "Olja", "amount": 1, "unit": "st"}, {"name": "Torkade lasagneplattor", "amount": 9, "unit": "st"}]',
 '["Tina spenaten enligt anvisning på förpackningen. Pressa ut vätskan ur spenaten.", "Sätt ugnen på 225°C.", "Blanda spenaten med smulad fetaost, cottage cheese och pressad vitlök. Krydda med salt och peppar.", "Skär laxen i ca 2 cm stora bitar och blanda med krossade tomater, vitt vin och salt.", "Lägg ut hälften av spenatröran i en oljad ugnssäker form, ca 20 x 30 cm (för 4 port). Varva sedan lasagneplattor och laxröra och avsluta med resten av spenatröran.", "Grädda lasagnen mitt i ugnen ca 30 minuter. Låt stå och vila ca 10 minuter."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_f8a25f20-6914-464f-80c0-10bf4f591b38', 'Stekt strömming med citruspuré och purjofräs', 4, '🐟', '["fisk", "husmanskost"]',
 '[{"name": "Potatis", "amount": 1, "unit": "kg"}, {"name": "Vispgrädde", "amount": 1.5, "unit": "dl"}, {"name": "Mjölk", "amount": 2, "unit": "dl"}, {"name": "Finrivet citronskal", "amount": 1, "unit": "msk"}, {"name": "Färskpressad citronjuice", "amount": 0.5, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Purjolök", "amount": 1, "unit": "st"}, {"name": "Smör till stekning", "amount": 2, "unit": "msk"}, {"name": "Strösocker", "amount": 1, "unit": "tsk"}, {"name": "Salt", "amount": 1, "unit": "krm"}, {"name": "Vitpeppar", "amount": 1, "unit": "krm"}, {"name": "Smör", "amount": 50, "unit": "g"}, {"name": "Grovt rågmjöl", "amount": 2, "unit": "dl"}, {"name": "Salt", "amount": 1.5, "unit": "tsk"}, {"name": "Vitpeppar", "amount": 1, "unit": "krm"}, {"name": "Strömmingsfiléer", "amount": 600, "unit": "g"}, {"name": "Smör", "amount": 1, "unit": "st"}]',
 '["Puré: Skala och koka potatisen i lättsaltat vatten. Häll av vattnet och låt potatisen ånga av.", "Värm grädde och mjölk.", "Mosa potatisen med potatisstöt eller elvisp. Tillsätt gräddmjölken, citronskal och -juice i moset. Smaka av med salt och peppar.", "Purjofräs: Ansa och skölj purjolöken. Skiva och fräs i smör i en stekpanna ca 2 minuter. Smaka av med socker, salt och vitpeppar.", "Brynt smör:Bryn smöret i en kastrull. Ställ åt sidan.", "Strömming: Blanda rågmjöl/ströbröd med salt och vitpeppar och häll ut på en tallrik. Vänd strömmingsfiléerna i blandningen.", "Stek strömmingen gyllene i smör i ca 2 minuter per sida.", "Servera strömmingen nystekt med citruspuré, purjofräs och brynt smör."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_fb534263-8c52-47fd-a654-a2ac1e5e4d4a', 'Torsk puttanesca', 4, '🐟', '["fisk", "gryta"]',
 '[{"name": "Tinad fryst torsk", "amount": 600, "unit": "g"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Vitlöksklyftor", "amount": 4, "unit": "st"}, {"name": "Röd peppar", "amount": 1, "unit": "st"}, {"name": "Sardellfiléer", "amount": 4, "unit": "st"}, {"name": "Svarta urkärnade oliver", "amount": 2, "unit": "dl"}, {"name": "Olivolja", "amount": 3, "unit": "msk"}, {"name": "Krossade tomater", "amount": 2, "unit": "förp"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}, {"name": "Kruka basilika", "amount": 1, "unit": "st"}, {"name": "Bröd, kokt potatis", "amount": 1, "unit": "st"}]',
 '["Dela torsken i 8 bitar och krydda med salt runtom. Låt stå ca 15 minuter.", "Skala vitlöken. Dela och kärna ur chilin. Finhacka vitlök och chili. Hacka sardellerna och halvera oliverna.", "Fräs vitlök och chili i oljan i en gryta några minuter. Tillsätt sardeller, oliver och krossade tomater och låt koka på svag värme under lock ca 15 minuter. Smaka av med salt och peppar.", "Lägg ner fisken och låt sjuda 5–10 minuter.", "Till servering: Toppa med basilika och servera gärna med bröd, kokt potatis eller matgryn."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_243e7b1a-8f3e-4cb6-9868-772bd943feb2', 'Lax i kokosmjölk med miso och sockerärtor', 4, '🐟', '["fisk", "lax", "pasta"]',
 '[{"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Tinad fryst", "amount": 500, "unit": "g"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Salladslökar", "amount": 4, "unit": "st"}, {"name": "Fryst", "amount": 1, "unit": "msk"}, {"name": "Fryst", "amount": 2, "unit": "msk"}, {"name": "Olja", "amount": 2, "unit": "msk"}, {"name": "Kokosmjölk", "amount": 1, "unit": "förp"}, {"name": "Vatten", "amount": 2, "unit": "dl"}, {"name": "Misopasta", "amount": 2, "unit": "msk"}, {"name": "Japansk soja", "amount": 2, "unit": "msk"}, {"name": "Tinade frysta sockerärtor", "amount": 250, "unit": "g"}, {"name": "Fryst", "amount": 2, "unit": "msk"}, {"name": "Färskpressad limejuice", "amount": 1, "unit": "msk"}]',
 '["Koka riset enligt anvisningen på förpackningen.", "Skär laxen i tärningar och krydda med saltet runtom.", "Skiva salladslöken tunt och spar lite av det gröna att toppa med. Stek salladslök, vitlök och chili i oljan. Tillsätt kokosmjölk, vatten, miso och soja och koka upp.", "Tillsätt laxen och socker­ärtor och låt sjuda ca 5 minuter. Rör ner koriander och limejuice. Smaka av med salt.", "Servera med kokt ris och toppa med resten av salladslöken."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_f50157ae-8244-424f-98a6-52b40fe4cf1c', 'Poké bowl med lax och kimchi', 4, '🐟', '["fisk", "lax"]',
 '[{"name": "Röd chilifrukt", "amount": 0.5, "unit": "st"}, {"name": "Finriven ingefära", "amount": 1, "unit": "msk"}, {"name": "Färskpressad limejuice", "amount": 0.5, "unit": "dl"}, {"name": "Japansk soja", "amount": 1, "unit": "dl"}, {"name": "Mirin", "amount": 2, "unit": "msk"}, {"name": "Sesamolja", "amount": 2, "unit": "msk"}, {"name": "Lax i bit", "amount": 200, "unit": "g"}, {"name": "Schalottenlök", "amount": 1, "unit": "st"}, {"name": "Sushiris", "amount": 4, "unit": "port"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Mirin", "amount": 3, "unit": "msk"}, {"name": "Kokosgrädde", "amount": 1, "unit": "dl"}, {"name": "Japansk soja", "amount": 0.5, "unit": "dl"}, {"name": "Mirin", "amount": 2, "unit": "msk"}, {"name": "Tahini", "amount": 0.75, "unit": "dl"}, {"name": "Finriven ingefära", "amount": 1, "unit": "tsk"}, {"name": "Röd chilifrukt", "amount": 0.25, "unit": "st"}, {"name": "Färskpressad lime", "amount": 0.5, "unit": "msk"}, {"name": "Flytande honung", "amount": 1, "unit": "tsk"}, {"name": "Färdig kimchi", "amount": 3, "unit": "dl"}, {"name": "Urgröpt, tärnad avokado", "amount": 1, "unit": "st"}, {"name": "Gurka i bitar", "amount": 0.25, "unit": "st"}, {"name": "Kruka koriander", "amount": 1, "unit": "st"}, {"name": "Strimlade salladslökar", "amount": 4, "unit": "st"}, {"name": "Vita", "amount": 1, "unit": "msk"}, {"name": "Rostad lök", "amount": 1, "unit": "dl"}]',
 '["Marinad: Dela, kärna ur och finhacka chilin. Skala och riv ingefära fint på ett rivjärn. Pressa ur drygt 1/2 dl limejuice (ta undan 1/2 msk till sesamsåsen). Blanda allt till en marinad.", "Lax: Skär laxen i cm-stora tärningar. Skala och finhacka schalottenlöken. Blanda lax och lök med marinaden. Låt marinera i kylen 10–60 minuter. Ju längre den marinerar desto mer smak.", "Ris: Koka riset enligt anvisningen på förpackningen med salt.", "Ta från värmen och smaksätt det varma riset med mirin. Låt svalna tills riset är ljummet.", "Sesamsås: Mixa kokosgrädde, soja, mirin, tahini, ingefära, röd chili, limejuice och honung slätt med en stavmixer.", "Till servering: Lägg upp ris runt kanterna i skålar (detta för att det inte enbart ska bli ris i bottnen). Lägg på marinerad lax, färdig kimchi eller gör din egen snabba kimchi, avokado, gurka och koriander. Ringla över sesamsås. Strö över salladslök, sesamfrön och rostad lök."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_f9d0bc30-7346-4cab-9b6a-68371e8a69cd', 'Tonfiskröra med äpple', 4, '🐟', '["fisk", "pasta"]',
 '[{"name": "Tonfisk i vatten", "amount": 2, "unit": "burk"}, {"name": "Crème fraiche", "amount": 1, "unit": "dl"}, {"name": "Majonnäs", "amount": 3, "unit": "msk"}, {"name": "Hackade soltorkade tomater", "amount": 3, "unit": "st"}, {"name": "Grovhackad färsk basilika", "amount": 0.5, "unit": "dl"}, {"name": "Finhackad rödlök", "amount": 0.5, "unit": "st"}, {"name": "Tärnat syrligt äpple", "amount": 1, "unit": "st"}, {"name": "Färskpressad citronjuice", "amount": 1, "unit": "msk"}, {"name": "Tabasco", "amount": 2, "unit": "krm"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Svartpeppar", "amount": 2, "unit": "krm"}, {"name": "Rostat surdegsbröd", "amount": 1, "unit": "st"}, {"name": "Blandsallad", "amount": 1, "unit": "st"}, {"name": "Nykokt pasta", "amount": 1, "unit": "st"}]',
 '["Häll av tonfisken. Blanda tonfisken med crème fraiche, majonnäs, soltorkade tomater, basilika, rödlök, äpple, citronjuice och tabasco. Krydda med salt och svartpeppar.", "Serveringsförslag: Servera gärna tonfiskröran på rostat levain, toppa salladen med röran eller blanda den med nykokt pasta."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_d390eef5-f87d-4cd6-8159-3b477e0bb102', 'Allt på en plåt med lax och mango', 4, '🐟', '["fisk", "lax"]',
 '[{"name": "Kokosmjölk", "amount": 2, "unit": "dl"}, {"name": "Vatten", "amount": 4.5, "unit": "dl"}, {"name": "Grönsaksbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Ris", "amount": 3, "unit": "dl"}, {"name": "Laxfilé", "amount": 600, "unit": "g"}, {"name": "Salta jordnötter", "amount": 0.5, "unit": "dl"}, {"name": "Ströbröd", "amount": 0.5, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Fryst broccoli", "amount": 300, "unit": "g"}, {"name": "Saften av 1 lime", "amount": 1, "unit": "st"}, {"name": "Sweet chilisås", "amount": 1, "unit": "dl"}, {"name": "Japansk soja", "amount": 1, "unit": "msk"}, {"name": "Fryst mango", "amount": 250, "unit": "g"}]',
 '["Tina mangon.", "Sätt ugnen på 225°C", "Kokosris: Koka upp kokosmjölken med vattnet och smulad buljongtärning. Rör i riset och sjud under lock enligt tidsangivelsen på risförpackningen.", "Lax: Skär laxen i portionsbitar. Hacka jordnötterna och blanda med ströbrödet. Krydda laxen med salt och peppar och vänd därefter laxbitarna i jordnötsblandningen.", "Lägg laxen på ett bakplåtspapper på plåt med kanter eller i en ugnsform tillsammans med den frysta broccolin. Tillaga i ca 15 minuter i mitten av ugnen, eller tills laxen har en innertemperatur på 56°C.", "Sweet chilisås: Pressa saften ur limen. Blanda sweet chilisås med limesaften och soja.", "Servera laxen med broccoli, mango, kokosris och sås."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_fd137bc7-0caf-4a9e-a1e5-f5f9f07b01cc', 'Arepa playera – Majsbröd med fiskragu och koriandermajonnäs', 4, '🐟', '["fisk"]',
 '[{"name": "Vatten", "amount": 6, "unit": "dl"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Vitt majsmjöl", "amount": 5, "unit": "dl"}, {"name": "Neutral rapsolja", "amount": 2, "unit": "msk"}, {"name": "Vatten", "amount": 5, "unit": "dl"}, {"name": "Torskfilé", "amount": 600, "unit": "g"}, {"name": "Gula lökar", "amount": 2, "unit": "st"}, {"name": "Vitlöksklyftor", "amount": 2, "unit": "st"}, {"name": "Stjälkselleri", "amount": 2, "unit": "st"}, {"name": "Röd paprika", "amount": 1, "unit": "st"}, {"name": "Neutral rapsolja", "amount": 3, "unit": "msk"}, {"name": "Tomatpuré", "amount": 0.5, "unit": "dl"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Svartpeppar", "amount": 1, "unit": "krm"}, {"name": "Salladslökar", "amount": 2, "unit": "st"}, {"name": "Jalapeño", "amount": 1, "unit": "st"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Majonnäs", "amount": 2, "unit": "dl"}, {"name": "Riven ingefära", "amount": 1, "unit": "msk"}, {"name": "Kruka koriander", "amount": 1, "unit": "st"}, {"name": "Limeklyftor", "amount": 1, "unit": "st"}]',
 '["Arepas: Vispa ihop ljummet (37°C) vatten och salt i en bunke. Rör ner majsmjöl till en smidig deg. Degen sväller snabbt, tillsätt inte mer mjöl om den känns lös.", "Forma 8 runda bröd (för 4 port), ca 10 cm i diameter och 1 ½ cm tjocka, med oljade händer. Stek i lite olja på medelvärme ca 5 minuter på varje sida. Låt svalna på bänken under bakduk.", "Sätt ugnen på 180°C och värm bröden cirka 10 minuter innan servering.", "Ragu: Koka upp vattnet i en kastrull som rymmer ca 1 l (för 4 port). Lägg i torskfiléerna och sjud ca 5 minuter tills de är precis genomkokta.", "Lägg torsken i en sil och fördela i mindre bitar. Pressa ut vätskan ur fisken så den blir torr.", "Skala och finhacka lök, vitlöksklyftor. Finhacka selleri och urkärnad paprika. Fräs i olja ca 5 minuter. Tillsätt tomatpuré och stek ytterligare 10 minuter. Vänd ner fisken. Smaka av med salt och peppar.", "Koriandermajonnäs: Strimla salladslök och kärna ur och hacka jalapeño. Mixa slätt med stavmixer tillsammans med skalad vitlöksklyfta, hälften av majonnäsen, ingefära och koriander. Häll i en skål och blanda ner resten av majonnäsen. Smaka av med salt.", "Till servering: Skär upp arepas och fyll med fiskragu och koriandermajonnäs. Servera med limeklyftor."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_7e690e00-e527-4f8a-b6d9-09a640f45b9f', 'Sommarens poké bowl med sparris, marinerad lax och chili & citrusmajonnäs', 4, '🐟', '["fisk", "lax"]',
 '[{"name": "Vatten", "amount": 1.5, "unit": "dl"}, {"name": "Strösocker", "amount": 1, "unit": "dl"}, {"name": "Risvinäger", "amount": 0.5, "unit": "dl"}, {"name": "Salt", "amount": 0.5, "unit": "krm"}, {"name": "Vit sparris", "amount": 0.5, "unit": "förp"}, {"name": "Chiliflakes", "amount": 0.5, "unit": "msk"}, {"name": "Ris", "amount": 3, "unit": "dl"}, {"name": "Färska aprikoser", "amount": 8, "unit": "st"}, {"name": "Rädisor", "amount": 1, "unit": "knippe"}, {"name": "Vitkål", "amount": 100, "unit": "g"}, {"name": "Majonnäs", "amount": 1.5, "unit": "dl"}, {"name": "Citronsaft", "amount": 0.5, "unit": "msk"}, {"name": "Japansk soja", "amount": 0.5, "unit": "msk"}, {"name": "Srirachasås", "amount": 1, "unit": "msk"}, {"name": "Sesamolja", "amount": 1, "unit": "msk"}, {"name": "Laxfilé", "amount": 400, "unit": "g"}, {"name": "Japansk soja", "amount": 0.5, "unit": "dl"}, {"name": "Sesamolja", "amount": 1, "unit": "tsk"}, {"name": "Färsk riven ingefära", "amount": 1, "unit": "tsk"}, {"name": "Citronsaft", "amount": 1, "unit": "tsk"}, {"name": "Grön tabasco", "amount": 2, "unit": "tsk"}, {"name": "Honung", "amount": 2, "unit": "tsk"}, {"name": "Wasabikryddad gurka med krispig purjolök", "amount": 1, "unit": "st"}]',
 '["Chilipicklad sparris: Koka upp vatten, socker, risvinäger och salt i en kastrull. Låt svalna.", "Skär bort 2-3 cm nedre delen på sparrisen. Hyvla sparrisen, med hjälp av en potatisskalare, i tunna långa skivor. Lägg i en burk tillsammans med chiliflakes. Häll över den kalla lagen. Sätt på locket och vänd burken upp och ner ett par gånger. Låt stå minst 15 minuter. Kan även göras dagen innan.", "Ris: Koka riset enligt anvisningen på förpackningen.", "Grönsaker: Kärna ur och dela aprikoserna i bitar. Ansa och skiva rädisorna tunt. Finstrimla vitkålen.", "Chili och citrusmajonnäs: Blanda ihop ingredienserna till såsen.", "Marinerad lax: Skär laxen i 2x2 cm stora tärningar. Blanda ihop ingredienserna till marinaden och häll över laxen och blanda runt. Servera direkt.", "Servering: Lägg ris i botten på skålar eller djupa tallrikar och toppa med alla tillbehör runt om. Ringla över chili- och citrusmajonnäs, eller servera den vid sidan av.", "Det är också gott att toppa poké bowlen med Wasabigurka med krispig purjolök"]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_d6aeb432-f88b-4383-9f36-4c97f03020a0', 'Potatisomelett med tonfisk', 2, '🐟', '["fisk", "vegetariskt"]',
 '[{"name": "Färska haricots verts", "amount": 0.5, "unit": "förp"}, {"name": "Ägg", "amount": 6, "unit": "st"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Fasta potatisar", "amount": 4, "unit": "st"}, {"name": "Dijonsenap", "amount": 1, "unit": "msk"}, {"name": "Vitvinsvinäger", "amount": 1, "unit": "msk"}, {"name": "Riven vitlöksklyfta", "amount": 0.5, "unit": "st"}, {"name": "Olivolja", "amount": 3, "unit": "msk"}, {"name": "Rödlök", "amount": 1, "unit": "st"}, {"name": "Körsbärstomater (6 st motsvarar ca 1/3 förp", "amount": 6, "unit": "st"}, {"name": "Grovhackad bladpersilja", "amount": 0.5, "unit": "dl"}, {"name": "Kapris", "amount": 1, "unit": "msk"}, {"name": "Svarta oliver", "amount": 0.5, "unit": "dl"}, {"name": "Tonfisk i olja", "amount": 1, "unit": "förp"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}]',
 '["Koka bönorna i saltat vatten ca 3 minuter, häll av och lägg åt sidan. Vispa ihop ägg och ½ tsk salt (för 2 port) till en jämn smet.", "Skala och skär potatisen i kuber (2x2 cm) och stek hälften i 2 msk olja ca 5 minuter. Krydda med ½ tsk salt (för 2 port).", "Häll hälften av äggsmeten i stekpannan, på potatisen och rör runt så att det bildas en lös äggröra. Låt stå på medelvärme och stek klart till en omelett. Upprepa samma process med resten av potatisen och smeten.", "Vispa ihop senap, vinäger och vitlök i en bunke. Vispa droppvis ner oljan till en dressing. Smaka av med salt och peppar.", "Skala och skiva löken tunt. Halvera tomaterna. Hacka persiljan. Blanda bönor, lök, tomater, kapris, oliver och persilja med dressingen. Häll av tonfisken.", "Toppa de stekta omeletterna med sallad och tonfisk."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_9c14b0b6-0e46-4694-bfaf-a33e16ce760c', 'Fiskpinneburgare med örtsås', 4, '🐟', '["barn", "fisk", "snabb", "vardag"]',
 '[{"name": "Crème fraiche", "amount": 2, "unit": "dl"}, {"name": "Frysta örter", "amount": 3, "unit": "msk"}, {"name": "Fiskpinnar", "amount": 1, "unit": "förp"}, {"name": "Smör", "amount": 1, "unit": "msk"}, {"name": "Tomater", "amount": 2, "unit": "st"}, {"name": "Hamburgerbröd", "amount": 4, "unit": "st"}, {"name": "Salladsmix", "amount": 65, "unit": "g"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}]',
 '["Rör ihop crème fraiche och örter, smaka av med salt och peppar.", "Stek fiskpinnarna i smöret i en stekpanna ca 4 minuter per sida.", "Skär tomaterna i skivor. Servera fiskpinnarna i bröden med alla tillbehör."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_7794a860-1137-4a04-a345-f50a513f3b3d', 'Sprödbakad torsk med Rhode Island', 4, '🐟', '["enkel", "fisk", "snabb", "vardag"]',
 '[{"name": "Potatis", "amount": 900, "unit": "g"}, {"name": "Sprödbakade torskfiléer", "amount": 2, "unit": "förp"}, {"name": "Crème fraiche", "amount": 2, "unit": "dl"}, {"name": "Chilisås", "amount": 2, "unit": "msk"}, {"name": "Salt", "amount": 2, "unit": "krm"}, {"name": "Peppar", "amount": 1, "unit": "krm"}, {"name": "Gurka", "amount": 1, "unit": "st"}, {"name": "Olja", "amount": 1, "unit": "msk"}]',
 '["Koka potatisen.", "Tillaga fisken enligt anvisningen på förpackningen.", "Rör ihop crème fraiche, chilisås, salt och peppar i en skål.", "Skär gurkan i stavar eller skivor.", "Servera torsken med potatis, gurka och Rhode Islandsås."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_3273556f-4555-4672-a7b5-8a09a33a5f23', 'Temaki sushi – sushistrutar', 4, '🐟', '["fisk"]',
 '[{"name": "Sushiris", "amount": 1, "unit": "st"}, {"name": "Gurka", "amount": 0.5, "unit": "st"}, {"name": "Avokador", "amount": 2, "unit": "st"}, {"name": "Krispsallad", "amount": 0.5, "unit": "förp"}, {"name": "Sushilax", "amount": 360, "unit": "g"}, {"name": "Noriark", "amount": 8, "unit": "st"}, {"name": "Gari ,", "amount": 1, "unit": "förp"}, {"name": "Rostade sesamfrön", "amount": 2, "unit": "msk"}, {"name": "Ponzusoja", "amount": 0.5, "unit": "dl"}, {"name": "Regnbågslaxrom", "amount": 1, "unit": "st"}, {"name": "Japansk majonnäs", "amount": 1, "unit": "st"}, {"name": "Finstrimlad chili", "amount": 1, "unit": "st"}]',
 '["Tillaga sushiriset enligt detta recept Sushiris.", "Dela gurkan på hälften och skär den i strimlor. Dela, kärna ur och gröp ur avokadorna. Skär avokadon i 4 klyftor och sedan varje klyfta i 3 skivor på längden.", "Dela salladen i mindre bitar och skär laxen i ca 1x1 cm små kuber.", "Klipp noriarken på hälften åt samma håll som linjerna i arket.", "Lägg ca 2 msk sushiris på ena kortsidan och tryck ut tunt. Lägg därefter på sallad, gurka, avokado, lax, gari och strössla över sesamfrön.", "Topping: Rulla till en strut och servera med ponzu eller soja och eventuellt fiskrom, majonnäs och chili."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_c45dfe0f-1d59-4a9e-8141-754430f4a7ae', 'Fiskfärsbiffar med citronsås', 4, '🐟', '["fisk"]',
 '[{"name": "Potatis", "amount": 900, "unit": "g"}, {"name": "Kruka dill", "amount": 1, "unit": "st"}, {"name": "Babyspenat", "amount": 65, "unit": "g"}, {"name": "Olivolja", "amount": 2, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Clariasfärs från Gårdsfisk", "amount": 500, "unit": "g"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Vitpeppar", "amount": 1, "unit": "krm"}, {"name": "Ägg", "amount": 1, "unit": "st"}, {"name": "Vispgrädde", "amount": 2, "unit": "dl"}, {"name": "Smör", "amount": 2, "unit": "msk"}, {"name": "Citron", "amount": 1, "unit": "st"}, {"name": "Crème fraiche", "amount": 2, "unit": "dl"}]',
 '["Potatis: Skala och koka potatisen.", "Fiskfärsbiffar: Mixa fiskfärsen i en matberedare tillsammans med salt och peppar så att den blir riktigt fast och drar ihop sig till en boll. Tillsätt ägget och mixa igen tills färsen drar ihop sig till en boll. Häll i vispgrädden i en tunn stråle, lite i taget, under fortsatt mixning till en lös smet.", "Sätt ugnen på 125°C.", "Forma smeten till 4 biffar med blöta händer (för 4 port). Bryn fiskfärsbiffarna i smöret i en stekpanna tills de har fin färg. Lägg dem i en ugnsform och ställ in i mitten av ugnen 10-15 minuter eller tills innertemperaturen på fisken är 58°C.", "Citronsås: Riv det yttersta skalet från citronen. Blanda skalet med crème fraichen och smaka av med salt och peppar och saft från citronen.", "Potatis: Skär dillen grovt. Häll av vattnet från potatisen och vänd försiktigt ner spenat, olivolja och dill. Smaksätt med salt och peppar.", "Servera fiskfärsbiffarna med potatis och citronsås."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_9e27e24d-e724-4295-bac2-70ecebf44492', 'Poké bowl med matjessill och ägg', 4, '🐟', '["fisk"]',
 '[{"name": "Sushiris", "amount": 4, "unit": "dl"}, {"name": "Vatten", "amount": 3.5, "unit": "dl"}, {"name": "Risvinäger", "amount": 2.5, "unit": "msk"}, {"name": "Strösocker", "amount": 1, "unit": "msk"}, {"name": "Ägg", "amount": 4, "unit": "st"}, {"name": "Majonnäs", "amount": 4, "unit": "msk"}, {"name": "Risvinäger", "amount": 1, "unit": "msk"}, {"name": "Japansk soja", "amount": 1, "unit": "msk"}, {"name": "Riven ingefära", "amount": 0.5, "unit": "msk"}, {"name": "Matjessill hela filéer", "amount": 1, "unit": "förp"}, {"name": "Salladslökar", "amount": 2, "unit": "st"}, {"name": "Rostad lök", "amount": 2, "unit": "msk"}, {"name": "Rostade sesamfrön", "amount": 1, "unit": "msk"}]',
 '["Ris: Lägg riset i iskallt vatten i 20 minuter, häll av och skölj riset försiktigt tills vattnet ser klart ut. Koka upp riset med 3 1/2 dl vatten (för 4 port). Sänk värmen och låt sjuda under lock ca 20 minuter. Stäng av värmen och låt stå med lock 10 minuter.", "Ägg: Koka upp vatten och sänk ner äggen i det kokande vattnet. Koka 5 ½ minut och häll av och skölj äggen i kallt vatten.", "Ris: Blanda risvinäger och socker tills sockret löst sig. Blanda ner i det varma riset.", "Dressing: Blanda majonnäs, risvinäger, soja och ingefära till en dressing.", "Häll av sillen och skär i bitar, skiva salladslöken fint och skala äggen.", "Lägg upp ris i 4 djupa tallrikar (för 4 port). Toppa med sill, ägg, dressing, salladslök, rostad lök och sesamfrön."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_b14d2fcb-8279-4ed8-8067-b0e36e3b69a4', 'S.O.S.-tallrik med potatis och picklad lök', 4, '🐟', '["fisk", "husmanskost"]',
 '[{"name": "Kokta kalla potatisar", "amount": 900, "unit": "g"}, {"name": "Rödlökar", "amount": 2, "unit": "st"}, {"name": "Ättiksprit 12%", "amount": 2, "unit": "msk"}, {"name": "Strösocker", "amount": 2, "unit": "msk"}, {"name": "Vatten", "amount": 3, "unit": "msk"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Matjessill hela filéer", "amount": 1, "unit": "burk"}, {"name": "Finriven pepparrot", "amount": 2, "unit": "msk"}, {"name": "Crème fraiche", "amount": 1, "unit": "dl"}, {"name": "Riven Västerbottensost", "amount": 1, "unit": "dl"}, {"name": "Smör", "amount": 100, "unit": "g"}, {"name": "Flingsalt", "amount": 2, "unit": "krm"}, {"name": "Plockad dill", "amount": 0.5, "unit": "dl"}, {"name": "Knäckebröd", "amount": 1, "unit": "st"}]',
 '["Koka potatisen och låt den kallna.", "Skala och skiva löken tunt. Blanda med ättika, socker, vatten och salt. Låt stå 20 minuter i rumstemperatur så att löken picklas och blir mjukare.", "Häll av och skär sillen i mindre bitar. Riv pepparroten. Blanda sill, crème fraiche, Västerbottensost och pepparrot.", "Krossa den kokta potatisen genom att trycka med ett glas så den mosas lätt. Stek de krossade potatisarna i smör i en stekpanna så de blir frasiga och får gyllenbrun färg, ca 10 minuter. Lägg upp på ett fat. Strö över flingsalt.", "Till servering: Toppa potatisen med sillröran, picklad rödlök och dill. Servera direkt tillsammans med knäckebröd."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_4b0f4b3f-4065-4442-9c83-0b0569050984', 'Klassiska köttbullar', 4, '🥩', '["husmanskost", "köttfärs", "vardag"]',
 '[{"name": "Mjölk", "amount": 0.5, "unit": "dl"}, {"name": "Vispgrädde", "amount": 0.5, "unit": "dl"}, {"name": "Ströbröd", "amount": 0.5, "unit": "dl"}, {"name": "Nöt", "amount": 500, "unit": "g"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Ägg", "amount": 1, "unit": "st"}, {"name": "Gul lök", "amount": 0.5, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "krm"}, {"name": "Socker", "amount": 0.5, "unit": "tsk"}, {"name": "Smör", "amount": 3, "unit": "msk"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Kokt potatis", "amount": 1, "unit": "st"}, {"name": "Lingonsylt", "amount": 1, "unit": "st"}, {"name": "Pressgurka", "amount": 1, "unit": "st"}]',
 '["Blanda mjölk, grädde och ströbröd. Låt svälla i 10 minuter.", "Blanda färsen med saltet tills färsen är fast, gärna med elvisp. Knäck i ägget och vispa ihop.", "Blanda sedan i ströbrödsblandningen. lök, peppar och socker i färsen.", "Fukta händerna med kallt vatten och forma köttbullar. Stek några i taget i smöret och oljan, skaka pannan då och då så att köttbullarna rullar runt och håller sig runda.", "Serveringsförslag: Servera köttbullarna med kokt potatis eller Potatismos , Lingonsylt och Pressgurka."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_5cc5770a-60ae-49f6-ab33-e9f8ecf39357', 'Raggmunk med fläsk', 4, '🥩', '["husmanskost", "vardag"]',
 '[{"name": "Vetemjöl", "amount": 2, "unit": "dl"}, {"name": "Mjölk", "amount": 4, "unit": "dl"}, {"name": "Ägg", "amount": 2, "unit": "st"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Fast potatis", "amount": 900, "unit": "g"}, {"name": "Skivat rimmat sidfläsk", "amount": 375, "unit": "g"}, {"name": "Smör", "amount": 2, "unit": "msk"}, {"name": "Morötter", "amount": 3, "unit": "st"}, {"name": "Lingonsylt", "amount": 1, "unit": "st"}]',
 '["Sätt ugnen på 125°C och sätt in en plåt.", "Raggmunk: Vispa mjölet med hälften av mjölken till en slät smet i en bunke. Vispa ner resten av mjölken, äggen och saltet.", "Skala och riv potatisen grovt. Krama ur vätskan och vänd ner den i smeten genast så att den inte mörknar.", "Strimla och stek fläsket krispigt i en stekpanna. Lägg det på plåten i ugnen och håll det varmt.", "Hetta upp lite av matfettet i en stekpanna och klicka ner smeten och stek raggmunkarna i omgångar. Håll dem varma på plåten i ugnen.", "Skala morötterna och skär i stavar.", "Till servering: Servera fläsket med raggmunkar, morötter och lingonsylt."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_b4cd8947-029f-4071-83d3-a43d71ac8c93', 'Kålpudding (grundrecept)', 4, '🥡', '["husmanskost", "vardag"]',
 '[{"name": "Vitkål", "amount": 1, "unit": "kg"}, {"name": "Olja", "amount": 2, "unit": "msk"}, {"name": "Ljus sirap", "amount": 2, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Svartpeppar", "amount": 2, "unit": "krm"}, {"name": "Gul lök", "amount": 1, "unit": "st"}, {"name": "Blandfärs", "amount": 500, "unit": "g"}, {"name": "Ägg", "amount": 1, "unit": "st"}, {"name": "Japansk soja", "amount": 2, "unit": "msk"}, {"name": "Vispgrädde", "amount": 1, "unit": "dl"}, {"name": "Konc kalvfond", "amount": 1, "unit": "msk"}, {"name": "Ljus sirap", "amount": 1, "unit": "msk"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Svartpeppar", "amount": 2, "unit": "krm"}, {"name": "Rårörda lingon", "amount": 1, "unit": "st"}]',
 '["Sätt ugnen på 200°C.", "Vitkål: Skär bort den hårda mittstocken på vitkålen och strimla resten fint. Bryn kålen i omgångar på hög värme i olja ca 5 minuter utan att det bränns.", "Lägg i en bunke och smaksätt med sirap, salt och svartpeppar.", "Färs: Skala och riv löken fint. Blanda löken och färsen med övriga ingredienser.", "Lägg hälften av kålen i en smord ugnssäker form, ca 30 x 25 cm (för 4 port). Lägg på färsen och täck med resterande kål. Grädda i mitten av ugnen ca 40 minuter.", "Till servering: Servera med Rårörda lingon och ev en sallad."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_32d804a3-1881-4f2c-aa32-c6abe7c04dd5', 'Klassisk Biff à la Lindström', 4, '🥩', '["husmanskost", "köttfärs"]',
 '[{"name": "Små potatisar", "amount": 900, "unit": "g"}, {"name": "Olja", "amount": 2, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Torkad timjan", "amount": 1, "unit": "tsk"}, {"name": "Schalottenlök", "amount": 1, "unit": "st"}, {"name": "Kapris", "amount": 0.5, "unit": "dl"}, {"name": "Inlagda rödbetor", "amount": 200, "unit": "g"}, {"name": "Högrevsfärs", "amount": 500, "unit": "g"}, {"name": "Äggulor", "amount": 4, "unit": "st"}, {"name": "Dijonsenap", "amount": 1.5, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Nymalen svartpeppar", "amount": 2, "unit": "krm"}, {"name": "Smör", "amount": 2, "unit": "msk"}, {"name": "Rumstempererat smör", "amount": 75, "unit": "g"}, {"name": "Kruka persilja", "amount": 0.5, "unit": "st"}, {"name": "Tomat", "amount": 1, "unit": "st"}]',
 '["Sätt ugnen på 225°C.", "Rostad potatis: Dela potatisen i halvor om den är stor och blanda med olja, salt och peppar och eventuellt timjan.", "Häll ut potatisen på en plåt med bakplåtspapper och sätt in mitt i ugnen ca 25 minuter, eller tills potatisen har fin färg och mjuk rakt igenom.", "Biff Lindström: Skala och grovriv löken på ett rivjärn. Grovhacka kaprisen. Skär rödbetorna i små tärningar. Blanda snabbt ihop färsen med lök, kapris, rödbetor, äggulor, senap, salt och peppar.", "Forma smeten till 8 biffar (för 4 port) med oljade händer.", "Stek biffarna i smör i en stekpanna på hög värme ca 1 minut. Vänd biffarna och stek ytterligare ca 3 minuter på lägre temperatur eller tills biffarna är klara och har en innertemperatur på 70°C.", "Persiljesmör: Hacka persiljan och blanda med smöret och krydda med salt och peppar.", "Servera biffarna med potatis, persiljesmör (eller se tips) och gärna tomat."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_3ec4e048-8799-401b-a80f-66dc11073c35', 'Plankstek', 4, '🥬', '["husmanskost", "vegetariskt"]',
 '[{"name": "Mjölig potatis", "amount": 1, "unit": "kg"}, {"name": "Äggulor", "amount": 2, "unit": "st"}, {"name": "Smör", "amount": 75, "unit": "g"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Vitpeppar", "amount": 1, "unit": "krm"}, {"name": "Planksteksplankor", "amount": 4, "unit": "st"}, {"name": "Tomater", "amount": 4, "unit": "st"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}, {"name": "Olivolja", "amount": 1, "unit": "msk"}, {"name": "Ryggbiff", "amount": 4, "unit": "skivor"}, {"name": "Smör", "amount": 25, "unit": "g"}, {"name": "Haricots verts", "amount": 150, "unit": "g"}, {"name": "Bearnaisesås", "amount": 3, "unit": "dl"}, {"name": "Gärna färsk persilja", "amount": 1, "unit": "st"}]',
 '["Potatismos: Skala och koka potatisen i saltat vatten.", "Sätt ugnen på 250°C.", "Passera potatisen genom en potatispress. Tillsätt äggulor, smör, salt och vitpeppar. Blanda väl. Spritsa ut moset runt om kanterna på plankorna.", "Dela tomaterna, krydda snittytan med salt och peppar. Ringla olivoljan över tomaterna. Lägg 2 tomathalvor på varje planka. Gratinera plankorna 10-15 minuter i övre delen av ugnen, tills moset fått färg.", "Stek köttet i resterande smör ca 2 minuter på varje sida. Krydda med salt och svartpeppar.", "Koka bönorna i saltat vatten ca 4 minuter.", "Lägg en köttbit på varje planka, fördela bönorna och bearnaisesås på plankorna. Toppa gärna med finhackad persilja."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_6d0d4651-b1e1-45cd-b93b-d0e51e08deca', 'Klassisk kalops', 4, '🥘', '["gryta", "husmanskost"]',
 '[{"name": "Nötkött t ex bog", "amount": 1, "unit": "kg"}, {"name": "Morötter", "amount": 4, "unit": "st"}, {"name": "Gula lökar", "amount": 2, "unit": "st"}, {"name": "Smör", "amount": 1, "unit": "msk"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Lagerblad", "amount": 3, "unit": "st"}, {"name": "Kryddpepparkorn", "amount": 30, "unit": "st"}, {"name": "Liter vatten", "amount": 1, "unit": "st"}, {"name": "Konc kalvfond", "amount": 2, "unit": "msk"}, {"name": "Majsstärkelse", "amount": 1.5, "unit": "msk"}, {"name": "Salt från kvarnen", "amount": 1, "unit": "st"}, {"name": "Peppar från kvarnen", "amount": 1, "unit": "st"}, {"name": "Kokt potatis", "amount": 1, "unit": "st"}, {"name": "Inlagda rödbetor", "amount": 1, "unit": "st"}]',
 '["Putsa köttet och skär bort senor från köttet. Skär det i 3x3 cm stora bitar.", "Skala och skär morötter och lök i ca 3 cm stora bitar.", "Bryn köttet i smör och olja i en gryta.", "Tillsätt morötter, lök, lagerblad och kryddpeppar. Låt fräsa några minuter under omrörning.", "Häll på vatten och kalvfond över allt kött och grönsaker i grytan.", "Koka upp och skumma av fettet.", "Låt sjuda under lock tills köttet är mjukt, ca 2-2 1/2 timmar. Skumma av fettet då och då. Ta av locket sista halvtimmen.", "Red kalopsen med majsttärkelse utblandat med lite vatten.", "Smaka av med salt och peppar.", "Till servering: Servera med kokt potatis och inlagda rödbetor. Severa gärna med bröd."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_71d7d9a7-a7e2-42fb-b01d-8ed8fda9e79f', 'Ugnsraggmunk med fläsk', 4, '🥩', '["husmanskost"]',
 '[{"name": "Frysta lingon", "amount": 2, "unit": "dl"}, {"name": "Strösocker", "amount": 1, "unit": "dl"}, {"name": "Smör", "amount": 2, "unit": "msk"}, {"name": "Ägg", "amount": 4, "unit": "st"}, {"name": "Mjölk", "amount": 4, "unit": "dl"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Vetemjöl", "amount": 1.5, "unit": "dl"}, {"name": "Bakpotatisar", "amount": 2, "unit": "st"}, {"name": "Morötter", "amount": 2, "unit": "st"}, {"name": "Skivat rimmat stekfläsk", "amount": 375, "unit": "g"}, {"name": "Smör", "amount": 1, "unit": "msk"}]',
 '["Sätt ugnen på 225°C.", "Rårörda lingon: Rör lingonen med sockret i en kastrull på svag värme tills sockret smälter. Låt svalna.", "Smörj en långpanna ca 30 x 40 cm med smör (för 4 port) .", "Vispa ihop ägg, 1 dl av mjölken och salt (för 4 port). Tillsätt mjölet och vispa till en slät smet. Vispa ner resten av mjölken.", "Skala och riv potatisen grovt. Blanda ner i smeten. Häll smeten i långpannan. Grädda i mitten av ugnen 30–35 minuter eller tills den är krispig och gyllene.", "Skala och riv morötterna. Stek fläsket knaprigt i smör. Servera raggmunken med fläsk, lingon och morötter."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_93aec2ce-687d-432a-8aa7-f436face10fa', 'Restpyttipanna', 4, '🌮', '["barn", "husmanskost"]',
 '[{"name": "Fast potatis", "amount": 1, "unit": "kg"}, {"name": "Gula lökar", "amount": 2, "unit": "st"}, {"name": "Korv och", "amount": 500, "unit": "g"}, {"name": "Gammalt bröd", "amount": 3, "unit": "skivor"}, {"name": "Äpple", "amount": 1, "unit": "st"}, {"name": "Olja", "amount": 2, "unit": "msk"}, {"name": "Smör", "amount": 2, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}, {"name": "Gräddfil", "amount": 1, "unit": "dl"}, {"name": "Tacosås", "amount": 1, "unit": "dl"}, {"name": "Ägg", "amount": 4, "unit": "st"}, {"name": "Smör", "amount": 1, "unit": "msk"}, {"name": "Fryst persilja", "amount": 1, "unit": "msk"}]',
 '["Sätt ugnen på 100°C.", "Skala och skär potatisen i ca 1 x 1 cm stora tärningar. Lägg i en bunke med kallt vatten. Häll av och skölj potatisen, låt rinna av. Skala och hacka löken. Skär kött och korv i ca 1 x 1 cm stora tärningar. Skär brödet och äpplet i 2 cm stora tärningar.", "Stek potatisen i omgångar i lite av oljan och smöret i en stekpanna tills den är mjuk och fått fin färg. Krydda med salt och peppar. Lägg upp i en ugnsform och håll varmt i ugnen.", "Stek lök och äpple i några minuter tills det mjuknar. Lägg lök och äpple på potatisen i ugnen. Stek köttet i samma stekpanna tillsammans med brödtärningarna. Blanda köttet med allt i ugnsformen.", "Till servering: Blanda gräddfil med tacosås och smaka av med salt och peppar. Stek äggen i lite smör i en stekpanna.", "Strö valfri ört över pytt i pannan och servera med ägg och tacosås."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_c0597474-6329-44c8-ba53-20aa2c29fc41', 'Nils Emils laxpudding med rökt lax', 4, '🐟', '["fisk", "husmanskost"]',
 '[{"name": "Mellanstora potatisar", "amount": 10, "unit": "st"}, {"name": "Skivad kallrökt lax", "amount": 300, "unit": "g"}, {"name": "Smör till formen", "amount": 1, "unit": "st"}, {"name": "Salt", "amount": 0.75, "unit": "tsk"}, {"name": "Ägg", "amount": 4, "unit": "st"}, {"name": "Mjölk", "amount": 2, "unit": "dl"}, {"name": "Vispgrädde", "amount": 2, "unit": "dl"}, {"name": "Smör", "amount": 2, "unit": "msk"}, {"name": "Smör", "amount": 100, "unit": "g"}, {"name": "Kruka finhackad dill", "amount": 1, "unit": "st"}]',
 '["Sätt ugnen på 175°C.", "Skala potatisen och skär den i ca 3 mm tjocka skivor. Varva potatis och lax i en smord ugnsform med höga kanter. Salta lätt på potatisen. Understa och översta lagret ska vara potatis.", "Vispa samman ägg, mjölk och grädde och häll blandningen i formen. Lägg på några smörklickar. Sätt in formen mitt i ugnen i ca 60 minuter.", "Dillsmör: Skira smöret: Smält det i en kastrull och slå över det i en annan - se till att bottensatsen inte kommer med. Blanda i dillen och servera dillsmöret till laxpuddingen."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_c1aa03a7-b4e4-48f6-9a34-9b21b7af3fef', 'Krämig pytt med primörer, kryddkorv och dijon', 6, '🥩', '["barn", "husmanskost"]',
 '[{"name": "Kall kokt potatis", "amount": 900, "unit": "g"}, {"name": "Knippmorötter", "amount": 6, "unit": "st"}, {"name": "Gröna sparrisar", "amount": 12, "unit": "st"}, {"name": "Rödlökar", "amount": 2, "unit": "st"}, {"name": "Kryddkorv", "amount": 2, "unit": "förp"}, {"name": "Matolja", "amount": 3, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}, {"name": "Eriksbergs Original 0,0% öl", "amount": 2, "unit": "dl"}, {"name": "Dijonsenap", "amount": 2, "unit": "msk"}, {"name": "Vispgrädde 40 %", "amount": 3, "unit": "dl"}, {"name": "Kruka persilja", "amount": 1, "unit": "st"}, {"name": "Gärna saltgurka i stavar", "amount": 1, "unit": "st"}, {"name": "Gärna Eriksbergs Original 0,0% öl", "amount": 1, "unit": "st"}, {"name": "Gärna äggulor", "amount": 1, "unit": "st"}]',
 '["Skär potatisen i grova bitar. Ansa och skär morötterna i ca 1 cm stora bitar. Skär bort ca 1 cm av botten på sparrisen. Skala dem om de är tjocka. Dela sparrisen på hälften. Skala och skär löken i fina klyftor (om färsk rödlök används; ansa och skär blasten i ca 2 cm stora bitar).", "Skär korv (och eventuellt kött) i ca 2 cm stora skivor eller bitar.", "Hetta upp en grillhäll eller muurikka eller en stor stekpanna (används stekpanna, stek då i omgångar och håll varmt i ugnen).", "Tillsätt oljan och lägg i morötterna och stek dem i 3-4 minuter, lägg därefter i potatis, lök och korv (och ev kött). Stek i 6-7 minuter tills det börjar få fin färg. Rör försiktigt om några gånger. Krydda med salt och peppar.", "Sänk värmen och häll i öl, senap och grädde samt lägg i sparrisen. Koka ihop pytten under omrörning i några minuter tills den blir lite krämig. Smaka av med salt och peppar.", "Servera pytten toppad med hackad persilja och gärna råa äggulor och saltgurka."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_b0cdc06e-21c8-4c25-a60f-04bf16f98302', 'Grillspett med fläskfilé', 4, '🥩', '["husmanskost"]',
 '[{"name": "Trägrillspett", "amount": 4, "unit": "st"}, {"name": "Fläskfilé", "amount": 600, "unit": "g"}, {"name": "Grillolja", "amount": 0.5, "unit": "dl"}, {"name": "Rödlök", "amount": 1, "unit": "st"}, {"name": "Citron", "amount": 1, "unit": "st"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Gärna bearnaisesås", "amount": 1, "unit": "st"}]',
 '["Blötlägg träspetten i ca 20 minuter.", "Putsa och skär köttet i 1/2 cm tunna skivor på snedden. Blanda skivorna med grilloljan och låt marinera i 30 minuter.", "Skala och dela löken. Skär bort rotfästet och plocka loss lökskivorna. Skär så att de blir ca 3 cm breda klyftor. Dela citronen på längden och skär den i skivor.", "Vik köttskivorna och varva dem med lök och citronskivor på spetten.", "Grilla eller stek spetten tills de får fin färg och stek därefter klart på indirekt värme på grillen eller i ugn (ca 200°C) i ca 10 minuter.", "Servera spetten, gärna med bearnaisesås."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_416c37f7-f659-427a-a46f-6739dc24a578', 'Små smörgåstårtor', 2, '🐟', '["fisk", "husmanskost"]',
 '[{"name": "Ägg", "amount": 2, "unit": "st"}, {"name": "Majonnäs", "amount": 3, "unit": "dl"}, {"name": "Crème fraiche", "amount": 1, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Skalade räkor", "amount": 2, "unit": "dl"}, {"name": "Kruka dill", "amount": 0.5, "unit": "st"}, {"name": "Färskpressad citronjuice", "amount": 1, "unit": "tsk"}, {"name": "Formfranska", "amount": 8, "unit": "skivor"}, {"name": "Gurka", "amount": 0.5, "unit": "st"}, {"name": "Kallrökt lax", "amount": 2, "unit": "skivor"}, {"name": "Caviar", "amount": 2, "unit": "msk"}, {"name": "Dillkvistar", "amount": 2, "unit": "st"}, {"name": "Majonnäs", "amount": 1, "unit": "st"}]',
 '["Lägg äggen i kokande vatten och koka dem i 9 minuter. Spola äggen kalla. Skala och hacka dem.", "Blanda majonnäs och crème fraiche och smaka av med salt och peppar.", "Krama försiktigt ur lite vätska ur räkorna. Hacka räkorna och dillen. Tag undan 1 1/2 dl av majonnäsblandningen (för 2 port). Blanda räkor, dill och ägg med resten av majonnäsblandningen. Smaka av med citronsaft och eventuellt mer salt och peppar.", "Skär bort kanterna på brödskivorna. Bygg två tårtor genom att fördela röran och mellan brödskivorna i 3 lager och lägg på sista skivorna som ett lock.", "Täck toppen och sidorna med majonnäsblandningen. Låt stå i kylen i minst 2 timmar.", "Garnering: Hyvla gurkan tunt på längden och skär remsorna i samma längd som höjden på tårtorna. Klä sidorna med gurkskivorna och toppa med lax, caviar, dillvippor och eventuellt lite extra majonnäs."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_f608ed3e-e3c4-4af3-8bdc-b2cdf80e6741', 'Isterband med ostgratinerad blomkål', 4, '🍲', '["husmanskost"]',
 '[{"name": "Blomkål", "amount": 800, "unit": "g"}, {"name": "Rapsolja", "amount": 1, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Mjölk", "amount": 5, "unit": "dl"}, {"name": "Majsstärkelse", "amount": 3, "unit": "msk"}, {"name": "Grönsaksbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Kruka persilja", "amount": 0.5, "unit": "st"}, {"name": "Riven Västerbottensost", "amount": 2, "unit": "dl"}, {"name": "Isterband", "amount": 2, "unit": "förp"}, {"name": "Buljongkokt potatis", "amount": 1, "unit": "st"}, {"name": "Inlagda rödbetor", "amount": 1, "unit": "st"}]',
 '["Sätt ugnen på 225°C.", "Ansa och skär blomkålen i buketter. Blanda dem med oljan i en ugnssäker form och krydda med salt. Sätt in mitt i ugnen tills blomkålen fått fin färg, ca 20 minuter", "Koka upp mjölken i en kastrull. Rör ut majsstärkelsen i lite vatten och rör ner i mjölken och låt koka ca 30 sekunder. Tillsätt buljongtärningen och smaka av med salt.", "Hacka persiljan och vänd ner i såsen.", "Häll såsen över blomkålen och strö över osten. Sätt in mitt i ugnen minuter tills osten börjar få färg, ca 10 minuter.", "Till servering: Tillaga isterbanden enligt anvisningen på förpackningen och servera med blomkål, potatis och rödbetor."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_321961e2-121e-4cd3-b4bd-77ca2eba9f71', 'Korv stroganoff med crème fraiche', 4, '🍗', '["barn", "husmanskost", "kyckling"]',
 '[{"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Falukorv", "amount": 500, "unit": "g"}, {"name": "Purjolök", "amount": 1, "unit": "st"}, {"name": "Smör", "amount": 1, "unit": "msk"}, {"name": "Tomatpuré", "amount": 4, "unit": "msk"}, {"name": "Lätt crème fraiche", "amount": 2, "unit": "dl"}, {"name": "Vatten", "amount": 1.5, "unit": "dl"}, {"name": "Paprikapulver", "amount": 1, "unit": "tsk"}, {"name": "Svartpeppar", "amount": 1, "unit": "krm"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Saltgurka", "amount": 1, "unit": "st"}]',
 '["Koka riset enligt anvisning på förpackningen.", "Strimla korven. Skölj, ansa och skär purjolöken i strimlor. Stek korv och purjolök i matfettet i en stekpanna.", "Tillsätt tomatpuré, crème fraiche, vatten, paprikapulver och peppar. Koka på svag värme i ca 5 minuter. Smaka av med salt.", "Till servering: Servera korsvstroganoffen med ris och saltgurka."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_aafbd0ae-cebe-4220-91c2-1d28bf989c15', 'Pölsa', 6, '🍲', '["husmanskost"]',
 '[{"name": "Nötbog", "amount": 700, "unit": "g"}, {"name": "Salt", "amount": 2, "unit": "tsk"}, {"name": "Morötter", "amount": 2, "unit": "st"}, {"name": "Purjolök", "amount": 1, "unit": "st"}, {"name": "Palsternacka", "amount": 1, "unit": "st"}, {"name": "Hela vitpepparkorn", "amount": 1, "unit": "tsk"}, {"name": "Torkad timjan", "amount": 2, "unit": "tsk"}, {"name": "Lagerblad", "amount": 2, "unit": "st"}, {"name": "Lever av nöt", "amount": 200, "unit": "g"}, {"name": "Korngryn", "amount": 3, "unit": "dl"}, {"name": "Buljong från köttkoket", "amount": 12, "unit": "dl"}, {"name": "Gula lökar", "amount": 2, "unit": "st"}, {"name": "Smör", "amount": 3, "unit": "msk"}, {"name": "Mejram", "amount": 2, "unit": "tsk"}, {"name": "Torkad timjan", "amount": 1, "unit": "tsk"}, {"name": "Ljus sirap", "amount": 1, "unit": "msk"}, {"name": "Nymalen vitpeppar", "amount": 1, "unit": "st"}, {"name": "Kokt potatis", "amount": 1, "unit": "st"}, {"name": "Stekt ägg", "amount": 1, "unit": "st"}, {"name": "Inlagda rödbetor", "amount": 1, "unit": "st"}, {"name": "Färsk hackad persilja", "amount": 1, "unit": "st"}]',
 '["Koka upp köttet i en stor gryta. Häll bort vattnet och spola av köttet.", "Lägg tillbaka köttet i grytan, fyll på med 2 liter vatten, tillsätt 2 tsk salt (för 6 port). Koka upp och skumma av.", "Ansa och skala och skär morot, purjo och palsternacka i ca 2 cm bitar. Tillsätt grönsakerna i grytan tillsammans med kryddorna. Koka under lock i ca 2 timmar, eller tills köttet är mört och har en innertemperatur på 85˚C, skumma av då och då.", "Ta upp köttet och låt det svalna.", "Putsa och skölj levern. Skär den i ca 5 x 5 cm stora bitar. Lägg bitarna i buljongen. Koka sakta 15-20 minuter, eller tills köttet har en innertemperatur på 70˚C.", "Ta upp levern och låt den svalna.", "Sila och spara buljongen.", "Skär kött och lever i små tärningar (det ska vara finhackat).", "Koka korngrynen under lock i 12 dl buljong från köttkoket i ca 30 minuter (om det inte är 12 dl buljong, fyll på med vatten och köttbuljongtärning).", "Skala och finhacka löken. Fräs löken i smöret tillsammans med mejram och timjan.", "Blanda korngryn, kött, lever och lök. Smaksätt med salt, peppar och sirap.", "Till servering: Servera pölsan gärna med kokt potatis, stekt ägg och inlagda rödbetor."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_51571ccc-25ef-4db0-9140-bd58ee1c6105', 'Klassisk laxpudding', 4, '🐟', '["fisk", "husmanskost", "lax"]',
 '[{"name": "Rimmad lax i tunna skivor", "amount": 250, "unit": "g"}, {"name": "Oskalad potatis", "amount": 900, "unit": "g"}, {"name": "Gul lök", "amount": 1, "unit": "st"}, {"name": "Kruka dill", "amount": 1, "unit": "st"}, {"name": "Ägg", "amount": 4, "unit": "st"}, {"name": "Mjölk", "amount": 3, "unit": "dl"}, {"name": "Vispgrädde", "amount": 1, "unit": "dl"}, {"name": "Smör + lite skirat smör", "amount": 50, "unit": "g"}, {"name": "Salt", "amount": 1, "unit": "tsk"}, {"name": "Grovmalen vitpeppar", "amount": 1, "unit": "krm"}]',
 '["Sätt ugnen på 200°C.", "Koka potatisen mjuk i lättsaltat vatten. Häll av och låt svalna.", "Skala och finhacka löken. Grovhacka dillen.", "Vispa ihop ägg, mjölk, grädde, salt och peppar.", "Skala potatisen och skär den i 1/2 cm tjocka skivor. Smöra en ugnssäker 2-liters form (för 4 port).", "Varva potatis, lax, hackad lök och dill. Understa och översta lagret ska vara potatis. Häll över äggblandningen. Klicka över smör.", "Tillaga i ugnen ca 45 minuter. Ta ut och låt svalna något. Servera med skirat smör."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_63ee1d4d-2ca7-4f6e-a4b4-4ccce96d54e4', 'Ugnsbakad torsk med äggsås', 4, '🐟', '["fisk", "husmanskost"]',
 '[{"name": "Torsk", "amount": 500, "unit": "g"}, {"name": "Vatten", "amount": 1, "unit": "l"}, {"name": "Salt", "amount": 0.5, "unit": "dl"}, {"name": "Hackad dill", "amount": 2, "unit": "msk"}, {"name": "Smör", "amount": 25, "unit": "g"}, {"name": "Smör", "amount": 25, "unit": "g"}, {"name": "Vetemjöl", "amount": 2, "unit": "msk"}, {"name": "Vispgrädde", "amount": 2.5, "unit": "dl"}, {"name": "Mjölk", "amount": 2, "unit": "dl"}, {"name": "Finrivet citronskal", "amount": 1, "unit": "tsk"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Vitpeppar", "amount": 2, "unit": "krm"}, {"name": "Hårdkokta ägg", "amount": 3, "unit": "st"}, {"name": "Hackad persilja", "amount": 2, "unit": "dl"}, {"name": "Kokt potatis", "amount": 1, "unit": "st"}]',
 '["Sätt ugnen på 200°C.", "Skär torsken i 4 bitar (för 4 port). Vispa ihop vatten och salt några minuter tills saltet löses upp. Lägg i torsk och dill, låt rimma 10 minuter.", "Ta upp torsken och skölj den hastigt i kallt vatten och lägg i en ugnsform. Klicka över smöret och häll ½ dl vatten (för 4 port) i botten på formen. Täck med aluminiumfolie. Ställ in i mitten av ugnen ca 15 minuter.", "Äggsås: Smält smöret i en kastrull och rör ner mjölet. Tillsätt grädde, mjölk och citronskal under vispning. Låt koka upp och koka på svag värme några minuter under omrörning. Smaka av med salt och peppar.", "Grovhacka äggen och vänd ner tillsammans med persiljan. Servera torsken med såsen och kokt potatis."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_89ec5e08-05ef-4440-86da-cde7fbae32ed', 'Salsicciapasta', 4, '🍝', '["barn", "pasta", "snabb", "vardag"]',
 '[{"name": "Pasta", "amount": 400, "unit": "g"}, {"name": "Zucchini", "amount": 1, "unit": "st"}, {"name": "Schalottenlökar", "amount": 2, "unit": "st"}, {"name": "Vitlöksklyftor", "amount": 2, "unit": "st"}, {"name": "Hela fänkålsfrön", "amount": 1, "unit": "tsk"}, {"name": "Färsk salsicciafärs", "amount": 400, "unit": "g"}, {"name": "Olivolja", "amount": 1, "unit": "msk"}, {"name": "Vitt vin", "amount": 1, "unit": "dl"}, {"name": "Vispgrädde", "amount": 3, "unit": "dl"}, {"name": "Chiliflakes", "amount": 0.5, "unit": "tsk"}, {"name": "Finriven parmesan", "amount": 2, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Riven parmesan", "amount": 1, "unit": "st"}]',
 '["Koka pastan enligt anvisning på förpackningen.", "Ansa och skär zucchinin i små tärningar.", "Skala och finhacka schalottenlök och vitlök.", "Stöt fänkålsfröna grovt i en mortel.", "Snitta upp korvarna och gröp ur färsen. Stek salsicciafärsen i olivoljan i en stekpanna. Finfördela färsen med en träslev.", "Tillsätt lökhacket, fänkålsfrö och zucchini. Stek ytterligare några minuter.", "Tillsätt vinet och låt det koka in. Rör ner grädde och chiliflakes och låt sjuda 5 minuter.", "Riv parmesanosten och rör ner i den i såsen, smaka av med salt och peppar. Blanda pastan med såsen.", "Till servering: Toppa pastan med nymalen svartpeppar och lite extra ost."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_b319425d-ffba-4c12-b6c1-64888650fe71', 'Snabb chili con carne', 4, '🥬', '["enkel", "snabb", "vardag", "vegetariskt"]',
 '[{"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Blandfärs", "amount": 500, "unit": "g"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Tomatpuré", "amount": 2, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Chilipulver", "amount": 1, "unit": "krm"}, {"name": "Vita bönor i tomatsås", "amount": 2, "unit": "förp"}, {"name": "Majskorn", "amount": 1, "unit": "förp"}, {"name": "Vatten", "amount": 0.5, "unit": "dl"}]',
 '["Koka riset enligt anvisningen på förpackningen.", "Stek färsen i oljan i en stekpanna. Rör i tomatpurén och krydda med salt, peppar och chilipulver.", "Rör ner vita bönorna, majsen (inklusive spad) och vattnet. Låt sjuda 5-10 minuter och smaka av med salt och peppar.", "Servera chilin med riset."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_71e6df22-7b34-4db7-befb-4d9ddec5a397', 'Ädelostpasta med purjolök och bacon', 4, '🍝', '["pasta", "snabb", "vardag"]',
 '[{"name": "Purjolök", "amount": 20, "unit": "cm"}, {"name": "Vitlöksklyftor", "amount": 3, "unit": "st"}, {"name": "Smör", "amount": 3, "unit": "msk"}, {"name": "Salt", "amount": 0.5, "unit": "krm"}, {"name": "Svartpeppar", "amount": 1, "unit": "krm"}, {"name": "Bacon", "amount": 1, "unit": "förp"}, {"name": "Pasta t ex linguine", "amount": 400, "unit": "g"}, {"name": "Vitt vin", "amount": 0.5, "unit": "dl"}, {"name": "Vispgrädde", "amount": 1.5, "unit": "dl"}, {"name": "Krämig mild ädelost", "amount": 100, "unit": "g"}, {"name": "Parmesan", "amount": 1, "unit": "st"}]',
 '["Sätt på en kastrull med vatten till pastan.", "Ansa och skölj purjolöken noga. Strimla purjolöken i 1 cm breda remsor på längden. Skala och skiva vitlöken tunt.", "Stek purjo- och vitlök mjuk i 1 msk av smöret (för 4 port) i en stekpanna på medelvärme. Krydda med salt och peppar och lägg åt sidan.", "Strimla baconet fint och stek till ett knaprigt smul i torr stekpanna. Låt rinna av på hushållspapper.", "Koka pastan enligt anvisning på förpackningen. Spara ca 1 1/2 dl pastavatten (för 4 port).", "Smält resten av smöret i en kastrull och tillsätt vin och grädde. Låt koka upp och späd med lite pastavatten. Bryt ädelosten i bitar och rör ner, låt smälta i såsen. Smaka av med salt och rikligt med nymalen svartpeppar.", "Rör i den kokta pastan i såsen och vänd ner purjolöken. Toppa med baconsmul, parmesan och peppar."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_e35e7972-eea1-40c8-a59f-f88ef24ab5e6', 'Gryta med kebab och dijonsenap', 4, '🥘', '["gryta", "snabb", "vardag"]',
 '[{"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Schalottenlökar", "amount": 2, "unit": "st"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Körsbärstomater", "amount": 250, "unit": "g"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Klassisk kebab", "amount": 1, "unit": "förp"}, {"name": "Tomatpuré", "amount": 3, "unit": "msk"}, {"name": "Vispgrädde", "amount": 3, "unit": "dl"}, {"name": "Dijonsenap", "amount": 1, "unit": "msk"}, {"name": "Torkad timjan", "amount": 1, "unit": "tsk"}, {"name": "Cornichons", "amount": 1, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Gräddfil", "amount": 1, "unit": "st"}, {"name": "Sallad", "amount": 1, "unit": "st"}, {"name": "Färsk timjan", "amount": 1, "unit": "st"}]',
 '["Koka riset enligt anvisningen på förpackningen.", "Skala och finhacka schalottenlök och vitlök, halvera tomaterna. Stek lök och vitlök ett par minuter i oljan, i en gryta utan att de tar färg. Tillsätt kebaben och stek tills den fått lite färg. Rör ner tomatpuré och stek ytterligare några minuter.", "Tillsätt tomater, grädde, dijonsenap och timjan i grytan. Rör om och låt koka ihop. Hacka cornichonerna och tillsätt i grytan. Smaka av med salt och peppar.", "Till servering: Servera grytan med ris och gräddfil och sallad. Dekorera ev med färsk timjan."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_1eb5bfe3-0f78-4eac-a0d0-f34fe6c55683', 'Prinskorv och snabbstuvade makaroner', 4, '🍝', '["barn", "pasta", "snabb", "vardag"]',
 '[{"name": "Makaroner", "amount": 4, "unit": "port"}, {"name": "Prinskorv", "amount": 600, "unit": "g"}, {"name": "Smör", "amount": 1, "unit": "tsk"}, {"name": "Mjölk", "amount": 5, "unit": "dl"}, {"name": "Majsstärkelse", "amount": 1.5, "unit": "msk"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Peppar", "amount": 1, "unit": "krm"}, {"name": "Körsbärstomater", "amount": 250, "unit": "g"}]',
 '["Koka makaronerna enligt anvisningen på förpackningen.", "Stek korvarna i matfettet.", "Häll av makaronerna noga, så att allt vatten rinner av (spola ej av dem).", "Blanda mjölk och majsstärkelse och rör ner i kastrullen och häll tillbaka makaronerna. Låt koka upp under omrörning och låt koka ca 5 minuter. Smaka av med salt och peppar.", "Servera makaronerna med korv och tomater."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_398d8e44-efd3-4c19-a860-09b4bb77e1e0', 'Snabblasagne', 4, '🍝', '["pasta", "snabb", "vardag"]',
 '[{"name": "Lätt crème fraiche", "amount": 5, "unit": "dl"}, {"name": "Pastasås tomat & basilika", "amount": 2, "unit": "förp"}, {"name": "Mjölk", "amount": 2, "unit": "dl"}, {"name": "Blandfärs", "amount": 500, "unit": "g"}, {"name": "Olja", "amount": 1, "unit": "tsk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}, {"name": "Köttbuljongtärningar", "amount": 1, "unit": "st"}, {"name": "Lasagneplattor", "amount": 12, "unit": "st"}, {"name": "Cosmopolitansallad", "amount": 1, "unit": "st"}]',
 '["Sätt ugnen på 200°C.", "Blanda fraiche, pastasås och mjölk i en stor kastrull.", "Stek färsen i oljan i en stekpanna och krydda med salt och peppar. Lägg färsen och smulad buljongtärning i kastrullen med tomatsåsen och låt koka upp.", "Varva sås och lasagneplattor i en ugnsform, storlek ca 20x30 cm (för 4 port), avsluta med ett lager sås.", "Sätt in formen mitt i ugnen ca 25 minuter eller enligt anvisning på lasagneförpackningen.", "Skär salladen i bitar och servera gärna med en Vinägrett.", "Servera lasagnen med sallad."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_4db808cf-85c7-4fb8-80f2-67f4866e2383', 'Snabb ramen', 1, '🥡', '["snabb", "vardag", "vegetariskt"]',
 '[{"name": "Majonnäs", "amount": 1, "unit": "msk"}, {"name": "Ägg", "amount": 1, "unit": "st"}, {"name": "Kallt vatten", "amount": 2, "unit": "msk"}, {"name": "Japansk soja", "amount": 0.5, "unit": "msk"}, {"name": "Snabbnudlar valfri smak", "amount": 1, "unit": "förp"}, {"name": "Frysta sojabönor", "amount": 1, "unit": "dl"}, {"name": "Kokt ägg", "amount": 1, "unit": "st"}, {"name": "Tabasco srirachasås", "amount": 1, "unit": "st"}, {"name": "Strimlad salladslök", "amount": 1, "unit": "st"}, {"name": "Rostad lök", "amount": 1, "unit": "st"}, {"name": "Rostade sesamfrön", "amount": 1, "unit": "st"}, {"name": "Chiliflakes", "amount": 1, "unit": "st"}]',
 '["Tina sojabönorna.", "Vispa ihop majonnäs, ägg, vatten, soja i en djup tallrik med en gaffel.", "Koka nudlarna enligt anvisningen på förpackningen tillsammans med sojabönorna.", "Tillsätt 1 dl (för 1 port) av den varma vätskan från nudlarna och vispa ihop med äggblandningen i tallriken. Lägg i sojabönor, nudlar och resterande vätska, rör försiktigt om.", "Serveringsförslag: Toppa ramen med valfri/valfria toppings."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_01857302-1b13-4ee8-8108-e874c393adbf', 'Snabb köttfärssås med tagliatelle', 4, '🍝', '["snabb", "vardag"]',
 '[{"name": "Broccoli", "amount": 250, "unit": "g"}, {"name": "Tagliatelle", "amount": 4, "unit": "port"}, {"name": "Blandfärs", "amount": 500, "unit": "g"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Ketchup", "amount": 1, "unit": "msk"}, {"name": "Köttbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Krossade tomater", "amount": 500, "unit": "g"}, {"name": "Oregano", "amount": 0.5, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}]',
 '["Sätt på vatten till pastan i en stor kastrull så att broccolin också får plats.", "Ansa och skär broccolin i buketter och skiva stammen. Koka pastan enligt anvisningen på förpackningen och låt broccolin koka med pastan när det återstår ca 4 minuter av koktiden.", "Stek färsen i oljan i en stekpanna. Rör ner ketchupen, smula i buljongtärningen, pressa i vitlöksklyftan, rör ner tomaterna och oreganon. Låt sjuda ca 5 minuter. Smaka av med salt och peppar.", "Servera pasta och broccoli med köttfärssås."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_213a5e30-5eb3-4780-890d-e589b8f506d2', 'Snabba kycklinggrytan', 4, '🍗', '["gryta", "kyckling", "snabb", "vardag"]',
 '[{"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Purjolök", "amount": 1, "unit": "st"}, {"name": "Strimlad kycklingfilé", "amount": 600, "unit": "g"}, {"name": "Olja", "amount": 1, "unit": "tsk"}, {"name": "Matlagningsgrädde", "amount": 2.5, "unit": "dl"}, {"name": "Tomatpuré", "amount": 2, "unit": "msk"}, {"name": "Senap", "amount": 1, "unit": "msk"}, {"name": "Kycklingbuljongtärning", "amount": 0.5, "unit": "st"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Persilja", "amount": 20, "unit": "g"}]',
 '["Koka riset enligt anvisningen på förpackningen.", "Ansa och skär purjolöken i bitar.", "Stek kycklingen och purjon i oljan tills de får färg. Rör i resten av ingredienserna och låt det koka upp och koka någon minut. Smaka av med salt och peppar. Hacka persiljan och strö över den.", "Servera grytan med riset och gärna en sallad."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_18f68c98-e04b-49e2-99c3-fa0abdbe4a38', 'Svamppizza med romanticatomater', 4, '🍽️', '["enkel", "snabb", "vardag"]',
 '[{"name": "Färska champinjoner", "amount": 250, "unit": "g"}, {"name": "Portabellosvamp", "amount": 200, "unit": "g"}, {"name": "Purjolök", "amount": 0.5, "unit": "st"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Pizzakit", "amount": 2, "unit": "förp"}, {"name": "Pesto basilika", "amount": 0.5, "unit": "dl"}, {"name": "Riven ost", "amount": 150, "unit": "g"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Torkad timjan", "amount": 2, "unit": "tsk"}, {"name": "Romanticatomater", "amount": 250, "unit": "g"}]',
 '["Sätt ugnen på 225°C, gärna varmluft.", "Ansa svampen och ansa och skölj purjon. Skiva svampen och purjolöken.", "Stek svampen och purjon i oljan i en stekpanna och pressa i vitlöken.", "Rulla ut pizzadegarna på varsin plåt och bred på den medföljande tomatsåsen. Ringla över pesto.", "Fördela svamp, lök, och den rivna osten på bottnarna. Krydda med salt, peppar och timjan.", "Grädda båda pizzorna i ugnen ca 10 minuter eller en i taget om du inte använder varmluftsugn.", "Till servering: Servera pizzorna med tomater."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_e63675ae-32e4-4914-8171-7807f0cff6c7', 'Halloumipasta med ärtor och soltorkad tomatcrème', 4, '🍝', '["pasta", "snabb", "vardag", "vegetariskt"]',
 '[{"name": "Pasta", "amount": 4, "unit": "port"}, {"name": "Frysta gröna ärtor", "amount": 250, "unit": "g"}, {"name": "Körsbärstomater", "amount": 250, "unit": "g"}, {"name": "Halloumi", "amount": 400, "unit": "g"}, {"name": "Olja", "amount": 2, "unit": "tsk"}, {"name": "Chiliflakes", "amount": 1, "unit": "krm"}, {"name": "Mjölk", "amount": 1.5, "unit": "dl"}, {"name": "Soltorkad tomatcrème", "amount": 140, "unit": "g"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Mâchesallad", "amount": 65, "unit": "g"}]',
 '["Koka pastan enligt anvisningen på förpackningen. Koka ärtorna tillsammans med pastan när det återstår 4 minuter av koktiden.", "Dela tomaterna i halvor.", "Skär halloumin i tärningar och stek dem i oljan i en stekpanna. Krydda med chiliflakes och lyft upp på en tallrik.", "Blanda mjölk och tomatcrème i stekpannan och koka upp. Smaka av med salt och peppar.", "Blanda pasta och ärtor med såsen och toppa med halloumi, tomater och sallad. Krydda gärna med lite extra peppar."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_ef3a0118-7924-4e32-a900-c8671b5f4488', 'Grillostpasta med tomatsallad', 4, '🍝', '["pasta", "snabb", "vardag"]',
 '[{"name": "Rödlök", "amount": 0.5, "unit": "st"}, {"name": "Grillost", "amount": 400, "unit": "g"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Matlagningsgrädde", "amount": 2.5, "unit": "dl"}, {"name": "Mjölk", "amount": 0.5, "unit": "dl"}, {"name": "Torkad oregano", "amount": 1, "unit": "tsk"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Pasta", "amount": 4, "unit": "port"}, {"name": "Frysta gröna ärtor", "amount": 250, "unit": "g"}, {"name": "Plommontomater", "amount": 500, "unit": "g"}, {"name": "Olivolja", "amount": 1, "unit": "msk"}, {"name": "Rödvinsvinäger", "amount": 0.5, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}]',
 '["Sätt på en stor kastrull med vatten som rymmer både pastan och ärtorna.", "Grillostsås: Skala och hacka löken. Skär osten i små tärningar. Stek lök och ost i oljan i en stekpanna.", "Koka pastan enligt anvisningen på förpackningen. Koka ärtorna tillsammans med pastan när det återstår 1 minut av pastans koktid.", "Grillostsås: Rör ner grädde och mjölk i stekpannan och låt det bli varmt. Krydda med oregano och peppar.", "Tomatsallad: Skär tomaterna i bitar och ringla över olivolja och vinäger. Krydda med salt och peppar.", "Servera pastan med såsen och tomaterna."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_7ab6cc62-1451-4f71-8712-3d51c14a01dc', 'Kyckling med woksås och nudlar', 4, '🍗', '["kyckling", "snabb", "vardag"]',
 '[{"name": "Äggnudlar", "amount": 4, "unit": "port"}, {"name": "Strimlad kycklingfilé", "amount": 600, "unit": "g"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Wokgrönsaker", "amount": 500, "unit": "g"}, {"name": "Woksås (gärna asian woksauce teriyaki", "amount": 1, "unit": "förp"}, {"name": "Lime", "amount": 1, "unit": "st"}, {"name": "Sesamfrö", "amount": 1, "unit": "msk"}]',
 '["Tina kycklingen.", "Koka nudlarna alt riset enligt anvisningen på förpackningen.", "Stek kycklingen i hälften av oljan i en stekpanna. Krydda med salt och peppar och lägg upp på en tallrik.", "Stek wokgrönsakerna i resten av oljan i stekpannan. Rör i kyckling och sås och låt det bli varmt.", "Skär limen i klyftor.", "Serveringsförslag: Servera kycklingwoken med nudlar och gärna lime och sesamfrö."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_0db710cb-10fd-4052-9a73-8e77dada5af0', 'Carbonaranudlar', 1, '🍗', '["kyckling", "snabb", "vardag"]',
 '[{"name": "Finskuren salladslök", "amount": 1, "unit": "st"}, {"name": "Bacon", "amount": 0.5, "unit": "förp"}, {"name": "Kyckling", "amount": 1, "unit": "förp"}, {"name": "Riven parmesan", "amount": 0.5, "unit": "dl"}, {"name": "Smör", "amount": 0.5, "unit": "msk"}, {"name": "Äggula", "amount": 1, "unit": "st"}, {"name": "Svartpeppar", "amount": 2, "unit": "krm"}]',
 '["Skär salladslöken fint, lägg åt sidan. Strimla bacon och stek knaprigt i torr stekpanna.", "Koka nudlarna enligt anvisning på förpackningen. Häll av men spara 1 dl av buljongen (för 1 port) och häll tillbaka tillsammans med nudlarna i kastrullen.", "Rör ner parmesan och smör i nudlarna till en jämn sås. Rör ner bacon.", "Häll upp i en skål och lägg på äggulan. Toppa med salladslök och svartpeppar."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_8ed1811a-da00-44f8-ab01-79b9e73d0e55', 'Färska udonnudlar med tahinisås', 4, '🥡', '["snabb", "vardag"]',
 '[{"name": "Riven ingefära", "amount": 1, "unit": "msk"}, {"name": "Salladslökar", "amount": 4, "unit": "st"}, {"name": "Tahini", "amount": 1, "unit": "dl"}, {"name": "Japansk soja", "amount": 3, "unit": "msk"}, {"name": "Kallt vatten", "amount": 0.5, "unit": "dl"}, {"name": "Ris", "amount": 1, "unit": "msk"}, {"name": "Färska udonnudlar", "amount": 2, "unit": "förp"}, {"name": "Rostade sesamfrön", "amount": 2, "unit": "msk"}]',
 '["Sätt på en kastrull med vatten till nudlarna. Skala och riv ingefäran fint. Ansa och finstrimla salladslöken.", "Vispa ihop tahini, soja, kallt vatten, ingefära och vinäger.", "Koka nudlarna enligt anvisning på förpackningen och lägg upp i 4 skålar (för 4 port). Lägg upp såsen i 4 små skålar och toppa med salladslök.", "Dippa de varma nudlarna i såsen och sesamfrön."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_63915abd-ebde-46eb-9607-caa862a0ba33', 'Dumplingssallad med sojamajonnäs', 4, '🐟', '["fisk", "snabb", "vardag"]',
 '[{"name": "Morötter", "amount": 400, "unit": "g"}, {"name": "Rödlök", "amount": 0.5, "unit": "st"}, {"name": "Spetskål", "amount": 400, "unit": "g"}, {"name": "Dippsås", "amount": 4, "unit": "påse"}, {"name": "Lime", "amount": 1, "unit": "st"}, {"name": "Fisksås", "amount": 0.5, "unit": "msk"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Majonnäs", "amount": 0.5, "unit": "dl"}, {"name": "Japansk soja", "amount": 1, "unit": "msk"}, {"name": "Frysta dumplings", "amount": 2, "unit": "förp"}, {"name": "Rapsolja", "amount": 2, "unit": "msk"}, {"name": "Vatten", "amount": 1, "unit": "dl"}, {"name": "Saltade jordnötter", "amount": 1, "unit": "dl"}, {"name": "Kruka koriander", "amount": 1, "unit": "st"}]',
 '["Sallad: Skala och strimla eller hyvla morötterna, gärna med en mandolin. Skala och skiva löken tunt. Strimla kålen. Blanda grönsakerna i en stor skål.", "Dressing: Häll den medföljande dippsåsen över grönsakerna. Pressa över saft från limen, häll över fisksåsen och skala och riv över vitlöken. Blanda allt noga.", "Sojamajonnäs: Blanda majonnäs och soja.", "Dumplings: Stek dumplingsen i oljan i en stekpanna tills de får fin färg på den platta sidan.", "Häll vattnet i stekpannan och lägg på ett lock, tills vattnet kokat in ca 5 minuter.", "Vänd ner dumplingsen i salladen och toppa med jordnötter och koriander. Servera med majonnäsen."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_e8a5ad68-132a-4d07-a2d3-289956bd4ab3', 'Falukorv- och zucchinigryta med pasta', 4, '🍝', '["barn", "gryta", "husmanskost", "pasta", "snabb", "vardag"]',
 '[{"name": "Falukorv", "amount": 550, "unit": "g"}, {"name": "Zucchini", "amount": 1, "unit": "st"}, {"name": "Olja", "amount": 0.5, "unit": "msk"}, {"name": "Pastasås med basilika", "amount": 1, "unit": "förp"}, {"name": "Matlagningsgrädde", "amount": 1, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Pasta", "amount": 4, "unit": "port"}]',
 '["Sätt på en kastrull med vatten till pastan.", "Skär falukorven och zucchinin i ca 2 cm stora tärningar.", "Stek korv- och zucchinitärningarna i oljan i en gryta. Sänk värmen och rör i pastasås och grädde. Låt grytan sjuda i 5 minuter, smaka sedan av med salt och peppar.", "Koka pastan enligt anvisningen på förpackningen", "Servera korvgrytan med pastan."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_33e41031-aa39-4430-9c04-465b77e4c934', 'Krämiga nudlar med färskost', 1, '🥗', '["snabb", "vardag"]',
 '[{"name": "Snabbnudlar", "amount": 1, "unit": "förp"}, {"name": "Cream cheese gärna", "amount": 3, "unit": "msk"}, {"name": "Mjölk", "amount": 1, "unit": "dl"}, {"name": "Srirachasås", "amount": 1, "unit": "msk"}, {"name": "Finskivad salladslök", "amount": 1, "unit": "st"}, {"name": "Koriander", "amount": 1, "unit": "st"}, {"name": "Rostade sesamfrön", "amount": 1, "unit": "st"}]',
 '["Värm nudlarna enligt anvisningen på förpackningen.", "Smält färskosten i mjölken i en stekpanna. Vispa i såsen från nudelförpackningen och srirachasås.", "Häll av nudlarna och blanda dem med såsen i stekpannan. Koka ihop i någon minut under omrörning.", "Servera nudlarna och toppa med valfri topping."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_d100d4ad-b0f5-4a87-8136-01eacc93cb6b', 'Chicken teriyaki med gurka', 4, '🍗', '["kyckling", "snabb", "vardag"]',
 '[{"name": "Ris", "amount": 4, "unit": "port"}, {"name": "Kycklinginnerfiléer", "amount": 600, "unit": "g"}, {"name": "Olja", "amount": 0.5, "unit": "msk"}, {"name": "Babyspenat", "amount": 65, "unit": "g"}, {"name": "Teriyakisås", "amount": 300, "unit": "ml"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Gurka", "amount": 1, "unit": "st"}]',
 '["Tina kycklingen om fryst används.", "Koka riset enligt anvisningen på förpackningen.", "Stek kycklingen runt om i oljan i en stor stekpanna ca 6 minuter.", "Sänk värmen och vänd i spenaten och teriyakisåsen och låt det bli varmt. Smaka ev av med salt och peppar.", "Dela gurkan på längden och skär den i skivor.", "Servera kycklingen i såsen med ris och gurka."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_c89827e9-b87c-4cd7-9587-5142d68134eb', 'Vegocurry med blomkål', 4, '🍝', '["pasta", "snabb", "vardag"]',
 '[{"name": "Gul lök", "amount": 1, "unit": "st"}, {"name": "Blomkål", "amount": 800, "unit": "g"}, {"name": "Olivolja", "amount": 2, "unit": "msk"}, {"name": "Röd currypasta", "amount": 2, "unit": "tsk"}, {"name": "Kokosmjölk", "amount": 400, "unit": "ml"}, {"name": "Vatten", "amount": 2, "unit": "dl"}, {"name": "Grönsaksbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Äggnudlar", "amount": 4, "unit": "port"}, {"name": "Sockerärtor", "amount": 200, "unit": "g"}]',
 '["Tina sockerärtorna om frysta används.", "Skala och skiva löken. Skär blomkålen i mindre bitar. Fräs lök och blomkål i olivoljan i en stor gryta. Rör ner currypastan och fräs ytterligare någon minut.", "Häll i kokosmjölk, vatten och smulad buljongtärning. Låt koka tills blomkålen är mjuk, ca 5 minuter. Smaka av med salt och peppar (se tips).", "Koka nudlarna enligt anvisningen på förpackningen.", "Strimla sockerärtorna.", "Servera curryn med nudlar och sockerärtor."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_dd7ab19d-ee6f-4367-9f02-da68dfef7bac', 'Krämig potatis- och purjolökssoppa', 4, '🍲', '["soppa", "vardag"]',
 '[{"name": "Potatis", "amount": 600, "unit": "g"}, {"name": "Purjolök", "amount": 1, "unit": "st"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Torkad timjan", "amount": 1, "unit": "tsk"}, {"name": "Grönsaksbuljong", "amount": 10, "unit": "dl"}, {"name": "Vispgrädde", "amount": 3, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Bröd , stekt bacon, finhackad persilja", "amount": 1, "unit": "st"}]',
 '["Skala och skiva potatisen. Skölj, ansa och strimla purjolöken.", "Fräs purjolöken i oljan i en stor kastrull.", "Tillsätt potatis, timjan och buljong. Låt soppan koka ca 15 minuter.", "Använd en stavmixer och mixa soppan slät.", "Häll grädden i soppan och koka upp.", "Smaka av med salt och peppar.", "Servera gärna soppan med bröd, stekt bacon och hackad persilja."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_dad68ff5-a7ff-4f17-850f-c30e26de572b', 'Tomatsoppa med basilikacrème', 4, '🍲', '["soppa"]',
 '[{"name": "Stor gul lök", "amount": 1, "unit": "st"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Smör", "amount": 1, "unit": "msk"}, {"name": "Färska tomater", "amount": 4, "unit": "st"}, {"name": "Krossade tomater", "amount": 1, "unit": "förp"}, {"name": "Tomatpuré", "amount": 2, "unit": "msk"}, {"name": "Oregano", "amount": 2, "unit": "tsk"}, {"name": "Grönsaksbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Vatten", "amount": 5, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Mellan", "amount": 1, "unit": "dl"}, {"name": "Crème fraiche", "amount": 2, "unit": "dl"}, {"name": "Basilikapesto", "amount": 1.5, "unit": "msk"}]',
 '["Skala och hacka löken och vitlöken. Fräs dem i smöret i en gryta eller kastrull.", "Skär de färska tomaterna i små tärningar. Blanda ner lök, krossade tomater, färska tomater, tomatpuré, oregano, smulad grönsaksbuljongtärning och vatten i grytan. Låt koka ca 10 minuter. Smaka av med salt och peppar.", "Mixa allt med stavmixer eller i en matberedare. Späd med grädde för att få soppan krämig.", "Basilikacrème: Blanda crème fraiche och pesto, smaka av med salt och peppar. Klicka basilikakrämen i soppan strax före servering eller servera bredvid."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_dcc0b606-ebae-452f-a537-7e83f8b7f77c', 'Jordärtskockssoppa med parmachips', 4, '🍲', '["soppa"]',
 '[{"name": "Parmaskinka", "amount": 4, "unit": "skivor"}, {"name": "Jordärtskockor", "amount": 500, "unit": "g"}, {"name": "Potatisar", "amount": 3, "unit": "st"}, {"name": "Vitlöksklyftor", "amount": 2, "unit": "st"}, {"name": "Smör", "amount": 1, "unit": "msk"}, {"name": "Vitt vin", "amount": 1.5, "unit": "dl"}, {"name": "Vatten", "amount": 0.5, "unit": "l"}, {"name": "Hönsbuljongtärningar", "amount": 2, "unit": "st"}, {"name": "Vispgrädde", "amount": 3, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Svartpeppar", "amount": 1, "unit": "st"}, {"name": "Timjankvistar", "amount": 8, "unit": "st"}]',
 '["Parmachips: Gör gärna parmachipsen i förväg. Om de går sönder kan du bryta dem i bitar och dekorera soppan med dessa. Lägg skivor av parmaskinka på en bakplåtspapperklädd plåt och torka i ugnen, 150°C, i ca 5 minuter. Låt svalna på papper.", "Soppa: Skala jordärtskockorna och potatisen. Skär i bitar. Finhacka vitlöken. Fräs ingredienserna med smör i en tjockbottnad kastrull.", "Häll över vinet och låt det koka ihop i en minut. Tillsätt vatten och lägg i buljongtärningarna. Rör om. Låt detta koka i 15 minuter, tills allt är mjukt.", "Mixa soppan i en matberedare eller med en mixerstav. Rör i grädden och värm. Smaka av med salt och peppar.", "Garnera med parmachips, timjan och ett par varv med svartpeppar."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_ad5374e8-c63e-4c62-94c6-9399baa995c3', 'Linssoppa med tomat', 4, '🍲', '["soppa", "vegetariskt"]',
 '[{"name": "Gul lök", "amount": 1, "unit": "st"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Vitlöksklyftor", "amount": 2, "unit": "st"}, {"name": "Torkad timjan", "amount": 0.5, "unit": "tsk"}, {"name": "Tomatpuré", "amount": 2, "unit": "msk"}, {"name": "Torkad basilika", "amount": 1, "unit": "tsk"}, {"name": "Paprikapulver", "amount": 2, "unit": "tsk"}, {"name": "Grönsaksbuljongtärningar", "amount": 2.5, "unit": "st"}, {"name": "Lagerblad", "amount": 2, "unit": "st"}, {"name": "Torkade röda linser", "amount": 2, "unit": "dl"}, {"name": "Krossade tomater", "amount": 1, "unit": "förp"}, {"name": "Vatten", "amount": 11, "unit": "dl"}, {"name": "Rödvinsvinäger", "amount": 0.5, "unit": "msk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}]',
 '["Skala och hacka löken och fräs den i oljan i en gryta eller kastrull.", "Pressa i vitlöken och rör i tomatpuré, timjan, basilika och paprikapulver.", "Tillsätt smulade buljongtärningar, lagerblad, linser, krossade tomater, och vatten.", "Låt koka 10-15 minuter eller tills linserna är mjuka. Smaka av med vinäger salt och peppar."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_c18e0e99-80a7-4472-9676-ab24292fc9ba', 'Fiskarhustruns fisksoppa', 4, '🐟', '["fisk", "lax", "soppa"]',
 '[{"name": "Små gula lökar", "amount": 10, "unit": "st"}, {"name": "Smör", "amount": 2, "unit": "msk"}, {"name": "Hela skalade tomater", "amount": 1, "unit": "burk"}, {"name": "Fiskbuljong", "amount": 5, "unit": "dl"}, {"name": "Vitt vin", "amount": 0.5, "unit": "dl"}, {"name": "Söndersmulad timjan", "amount": 1, "unit": "tsk"}, {"name": "Blandad fiskfilé", "amount": 300, "unit": "g"}, {"name": "Räkor med skal", "amount": 250, "unit": "g"}, {"name": "Vispgrädde", "amount": 1, "unit": "dl"}, {"name": "Finhackad dill", "amount": 1, "unit": "st"}, {"name": "Salt och peppar", "amount": 1, "unit": "st"}, {"name": "Bröd", "amount": 1, "unit": "st"}]',
 '["Skala lökarna och fräs dem i matfett. Tillsätt tomater, buljong, vin och timjan. Låt sjuda i ca 15 minuter.", "Skala räkorna.", "Skär fisken i små bitar. Lägg ner fiskbitarna i soppan. Sjud ytterligare i ca 5 minuter.", "Lägg räkorna i soppan, koka inte då blir räkorna torra och sega.", "Finhacka dillen. Vispa grädden till hårt skum och rör försiktigt ner den. Hetta upp soppan och smaka av med salt och peppar och strö dillen över.", "Till servering: Servera soppan med ett gott brytbröd."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_f85bfe52-4cbe-4d15-a02c-f2a9e6e8a3a4', 'Cowboysoppa', 4, '🍗', '["kyckling", "soppa", "vegetariskt"]',
 '[{"name": "Paprikor", "amount": 2, "unit": "st"}, {"name": "Bakpotatisar", "amount": 2, "unit": "st"}, {"name": "Blandfärs", "amount": 500, "unit": "g"}, {"name": "Olja", "amount": 1, "unit": "msk"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Paprikapulver", "amount": 1, "unit": "tsk"}, {"name": "Torkad oregano", "amount": 1, "unit": "tsk"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Vita bönor i tomatsås", "amount": 1, "unit": "förp"}, {"name": "Vispgrädde", "amount": 2.5, "unit": "dl"}, {"name": "Köttbuljong", "amount": 5, "unit": "dl"}]',
 '["Dela, kärna ur och skär paprikorna i tärningar. Skala och skär potatisarna i 2 cm stora tärningar.", "Stek paprikan och färsen i oljan i en gryta. Sänk värmen och pressa i vitlöken och krydda med paprikapulver, oregano, salt och peppar.", "Rör i potatis, vita bönor, grädde och buljong. Koka upp och sjud i 10 minuter eller tills potatisen är mjuk.", "Servera soppan."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_b5a4ed82-5a3b-4019-bb99-fb802e49741f', 'Morotssoppa med kokos', 4, '🍲', '["soppa"]',
 '[{"name": "Olivolja", "amount": 2, "unit": "msk"}, {"name": "Hackad gul lök", "amount": 1, "unit": "st"}, {"name": "Hackade vitlöksklyftor", "amount": 2, "unit": "st"}, {"name": "Skivade morötter", "amount": 500, "unit": "g"}, {"name": "Spiskummin", "amount": 1, "unit": "tsk"}, {"name": "Riven ingefära", "amount": 1, "unit": "msk"}, {"name": "Chiliflakes", "amount": 1, "unit": "krm"}, {"name": "Kokosmjölk", "amount": 1, "unit": "burk"}, {"name": "Konc grönsaksfond", "amount": 2, "unit": "msk"}, {"name": "Vatten", "amount": 6, "unit": "dl"}, {"name": "Färskpressad limejuice", "amount": 1, "unit": "msk"}, {"name": "Salt", "amount": 0.5, "unit": "tsk"}, {"name": "Pumpakärnor", "amount": 1, "unit": "msk"}]',
 '["Hetta upp olivolja i en stor gryta och fräs lök, vitlök, morötter, spiskummin, ingefära och chiliflakes tills de får lite färg.", "Häll i nästan all kokosmjölk i grytan ihop med grönsaksfond och vatten. Låt sjuda utan lock cirka 15–20 minuter eller tills morötterna är mjuka.", "Mixa soppan slät och tillsätt limejuice och salt. Späd ev med vatten.", "Till servering: Ringla över resten av kokosmjölken och toppa gärna med pumpakärnor vid servering."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_3791d704-396c-4e03-a2d4-97ce36d93e57', 'Lättlagad kräftsoppa', 4, '🍲', '["soppa"]',
 '[{"name": "Morötter", "amount": 3, "unit": "st"}, {"name": "Smör", "amount": 1, "unit": "msk"}, {"name": "Vetemjöl", "amount": 2, "unit": "msk"}, {"name": "Vatten", "amount": 1, "unit": "l"}, {"name": "Hönsbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Kräftost", "amount": 330, "unit": "g"}, {"name": "Crème fraiche", "amount": 2, "unit": "dl"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Kräftstjärtar", "amount": 1, "unit": "burk"}, {"name": "Dill", "amount": 1, "unit": "st"}, {"name": "Bröd", "amount": 1, "unit": "st"}]',
 '["Skala och grovriv morötterna, bryn dem i smör i en kastrull. Strö över mjöl. Häll i vatten och buljong. Koka i 5 minuter.", "Blanda ner kräftost och crème fraiche. Låt det koka upp igen. Salta och peppra.", "Till servering: Blanda gärna kräftor med finhackad dill och lägg i soppan vid servering. Servera tillsammans med bröd."]');

INSERT OR IGNORE INTO recipes (id, name, servings, emoji, tags, ingredients, instructions) VALUES
('rec_848791fb-69c8-46bc-a444-19edc861a1c5', 'Räksoppa med aioli', 4, '🐟', '["fisk", "soppa"]',
 '[{"name": "Bakpotatis", "amount": 1, "unit": "st"}, {"name": "Morötter", "amount": 0.5, "unit": "förp"}, {"name": "Matlagningsgrädde", "amount": 2.5, "unit": "dl"}, {"name": "Vatten", "amount": 2.5, "unit": "dl"}, {"name": "Fiskbuljongtärning", "amount": 1, "unit": "st"}, {"name": "Ask färsk persilja", "amount": 0.5, "unit": "st"}, {"name": "Passerade tomater", "amount": 500, "unit": "g"}, {"name": "Salt", "amount": 1, "unit": "st"}, {"name": "Peppar", "amount": 1, "unit": "st"}, {"name": "Frysta skalade räkor", "amount": 400, "unit": "g"}, {"name": "Bake off baguetter", "amount": 2, "unit": "st"}, {"name": "Vitlöksklyfta", "amount": 1, "unit": "st"}, {"name": "Majonnäs", "amount": 2, "unit": "dl"}]',
 '["Sätt ugnen på 220°C till baguetterna.", "Soppa: Skala och skär potatisen och morötterna i tärningar. Lägg tärningarna i en stor kastrull och häll i grädde, vatten och smulad fiskbuljongtärning. Låt koka ca 15 minuter eller tills potatisen är mjuk.", "Hacka persiljan.", "Baka bröden enligt anvisningen på förpackningen.", "Aioli: Pressa vitlöken i majonnäsen. Smaka av med salt och peppar.", "Soppa: Rör ner passerade tomater koka upp soppan och smaka av med salt och peppar. Lägg räkorna i soppan och låt de tina samt bli varma (koka inte för då blir räkorna sega).", "Servera soppan med persilja, aioli och baguette."]');
